'use client';

export const dynamic = 'force-dynamic';


import { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useRealtimeIncidents } from '@/lib/supabase/realtime';
import type { DBIncident } from '@/lib/supabase/types';
import {
  AlertTriangle, CheckCircle2, Clock, Radio, RefreshCw,
  Wifi, WifiOff, MapPin, Phone, X, ChevronRight,
  Activity, Users, ShieldCheck, Zap, Video as VideoIcon
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useWebRTC } from '@/lib/webrtc';

// ── helpers ────────────────────────────────────────────────────
function timeAgo(iso: string) {
  const diff = (Date.now() - new Date(iso).getTime()) / 1000;
  if (diff < 60) return `${Math.floor(diff)}s ago`;
  if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
  return `${Math.floor(diff / 3600)}h ago`;
}

const STATUS_CONFIG: Record<DBIncident['status'], { label: string; color: string; dot: string; icon: React.ElementType }> = {
  active:       { label: 'Active',       color: 'text-red-400',    dot: 'bg-red-500',    icon: AlertTriangle },
  acknowledged: { label: 'Acknowledged', color: 'text-yellow-400', dot: 'bg-yellow-400', icon: Clock },
  resolved:     { label: 'Resolved',     color: 'text-green-400',  dot: 'bg-green-500',  icon: CheckCircle2 },
  false_alarm:  { label: 'False Alarm',  color: 'text-gray-400',   dot: 'bg-gray-600',   icon: X },
};

const TYPE_EMOJI: Record<string, string> = {
  road_crash: '🚗', medical: '🏥', fire: '🔥', flood: '🌊', assault: '🚨', other: '⚠️',
};

// Mock stats for demo (replace with real Supabase aggregates)
const MOCK_STATS = [
  { label: 'Active',     value: '—', icon: Zap,        color: 'text-red-400',    bg: 'bg-red-500/10' },
  { label: 'Today',      value: '—', icon: Activity,   color: 'text-orange-400', bg: 'bg-orange-500/10' },
  { label: 'Responders', value: '4', icon: Users,       color: 'text-blue-400',   bg: 'bg-blue-500/10' },
  { label: 'Resolved',   value: '—', icon: ShieldCheck, color: 'text-green-400',  bg: 'bg-green-500/10' },
];

// ── Component ──────────────────────────────────────────────────
export default function AdminPage() {
  const { incidents, connectionStatus, error, updateIncidentStatus, refresh } = useRealtimeIncidents({ limit: 100 });
  const [selected, setSelected] = useState<DBIncident | null>(null);
  const [updating, setUpdating] = useState<string | null>(null);
  const [filter, setFilter] = useState<DBIncident['status'] | 'all'>('all');

  const [remoteStream, setRemoteStream] = useState<MediaStream | null>(null);
  const adminVideoRef = useRef<HTMLVideoElement>(null);

  // Admin WebRTC Hook for selected incident
  const { connected: webrtcConnected } = useWebRTC(
    selected?.id ?? null,
    'admin',
    null,
    (stream) => {
      setRemoteStream(stream);
      if (adminVideoRef.current) {
        adminVideoRef.current.srcObject = stream;
      }
    }
  );

  // Clear stream if selection changes or status is no longer active
  useEffect(() => {
    if (!selected || (selected.status !== 'active' && selected.status !== 'acknowledged')) {
      setRemoteStream(null);
    }
  }, [selected]);

  const activeCount  = incidents.filter(i => i.status === 'active').length;
  const resolvedCount = incidents.filter(i => i.status === 'resolved').length;
  const todayCount   = incidents.filter(i => new Date(i.created_at).toDateString() === new Date().toDateString()).length;

  const stats = MOCK_STATS.map(s => ({
    ...s,
    value: s.label === 'Active' ? String(activeCount) : s.label === 'Today' ? String(todayCount) : s.label === 'Resolved' ? String(resolvedCount) : s.value,
  }));

  const filtered = filter === 'all' ? incidents : incidents.filter(i => i.status === filter);

  async function handleStatusChange(incident: DBIncident, newStatus: DBIncident['status']) {
    setUpdating(incident.id);
    try {
      await updateIncidentStatus(incident.id, newStatus);
      if (selected?.id === incident.id) setSelected({ ...incident, status: newStatus });
    } catch (e) { console.error(e); }
    finally { setUpdating(null); }
  }

  return (
    <div className="min-h-screen bg-gray-950 text-white">
      {/* Top bar */}
      <header className="sticky top-0 z-20 bg-gray-950/90 backdrop-blur border-b border-gray-800 px-5 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-xl bg-red-600 flex items-center justify-center">
            <Radio size={15} className="text-white" />
          </div>
          <div>
            <h1 className="font-black text-base text-white leading-none">Control Room</h1>
            <p className="text-gray-500 text-[10px]">ROADSoS Admin</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {/* Live indicator */}
          <div className={cn('flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold border',
            connectionStatus === 'connected' ? 'bg-green-500/10 border-green-500/30 text-green-400' :
            connectionStatus === 'error'     ? 'bg-red-500/10 border-red-500/30 text-red-400' :
            'bg-yellow-500/10 border-yellow-500/30 text-yellow-400'
          )}>
            {connectionStatus === 'connected'
              ? <><Wifi size={11} /> Live</>
              : connectionStatus === 'error'
              ? <><WifiOff size={11} /> Error</>
              : <><WifiOff size={11} /> Connecting</>
            }
          </div>
          <button onClick={refresh} aria-label="Refresh incidents"
            className="w-8 h-8 rounded-xl bg-gray-800 flex items-center justify-center hover:bg-gray-700 transition-colors">
            <RefreshCw size={14} className="text-gray-400" />
          </button>
        </div>
      </header>

      <div className="px-4 py-4 space-y-4 pb-10">
        {/* Error banner */}
        {error && (
          <div className="bg-yellow-900/30 border border-yellow-700/50 rounded-xl px-4 py-2 text-yellow-300 text-sm flex items-center gap-2">
            <AlertTriangle size={14} />
            {error} — showing cached data
          </div>
        )}

        {/* Stats grid */}
        <div className="grid grid-cols-4 gap-2">
          {stats.map(s => {
            const Icon = s.icon;
            return (
              <div key={s.label} className={cn('rounded-2xl p-3 border border-gray-800', s.bg)}>
                <Icon size={16} className={cn('mb-1', s.color)} />
                <p className={cn('text-xl font-black', s.color)}>{s.value}</p>
                <p className="text-gray-500 text-[10px]">{s.label}</p>
              </div>
            );
          })}
        </div>

        {/* Filter tabs */}
        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
          {(['all', 'active', 'acknowledged', 'resolved', 'false_alarm'] as const).map(f => (
            <button key={f} onClick={() => setFilter(f)}
              className={cn('shrink-0 px-3 py-1.5 rounded-xl text-xs font-semibold border transition-all',
                filter === f ? 'bg-white text-gray-900 border-white' : 'bg-gray-900 border-gray-700 text-gray-400 hover:border-gray-500'
              )}>
              {f === 'all' ? 'All' : f === 'false_alarm' ? 'False Alarm' : STATUS_CONFIG[f].label}
              {f === 'active' && activeCount > 0 && (
                <span className="ml-1.5 bg-red-500 text-white rounded-full text-[9px] px-1.5 py-0.5">{activeCount}</span>
              )}
            </button>
          ))}
        </div>

        {/* Incident list + detail panel */}
        <div className="flex gap-3">
          {/* List */}
          <div className="flex-1 space-y-2 min-w-0">
            {filtered.length === 0 && (
              <div className="text-center py-16 text-gray-600">
                <CheckCircle2 size={32} className="mx-auto mb-3 opacity-50" />
                <p className="text-sm">No {filter !== 'all' ? filter : ''} incidents</p>
                <p className="text-xs mt-1">
                  {process.env.NEXT_PUBLIC_SUPABASE_URL?.includes('your-project')
                    ? 'Configure Supabase in .env.local to see real incidents'
                    : 'All clear'}
                </p>
              </div>
            )}
            <AnimatePresence initial={false}>
              {filtered.map((inc) => {
                const cfg = STATUS_CONFIG[inc.status];
                const Icon = cfg.icon;
                const isSelected = selected?.id === inc.id;
                return (
                  <motion.button
                    key={inc.id}
                    layout
                    initial={{ opacity: 0, y: -8 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, x: -20 }}
                    onClick={() => setSelected(isSelected ? null : inc)}
                    className={cn(
                      'w-full text-left bg-gray-900 border rounded-2xl p-4 transition-all',
                      isSelected ? 'border-red-500/50 bg-gray-800' : 'border-gray-800 hover:border-gray-700'
                    )}
                  >
                    <div className="flex items-start gap-3">
                      <div className="relative mt-0.5">
                        <span className="text-xl">{TYPE_EMOJI[inc.incident_type] ?? '⚠️'}</span>
                        {inc.status === 'active' && (
                          <span className="absolute -top-0.5 -right-0.5 w-2.5 h-2.5 rounded-full bg-red-500 border border-gray-900 animate-pulse" />
                        )}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className="font-bold text-sm text-white capitalize">{inc.incident_type.replace('_', ' ')}</span>
                          <span className={cn('flex items-center gap-1 text-xs font-semibold', cfg.color)}>
                            <Icon size={11} />{cfg.label}
                          </span>
                        </div>
                        <p className="text-gray-400 text-xs truncate mt-0.5">{inc.address ?? `${inc.lat?.toFixed(4)}, ${inc.lng?.toFixed(4)}`}</p>
                        <p className="text-gray-600 text-[10px] mt-1">{timeAgo(inc.created_at)} · ID {inc.id.slice(0, 8)}</p>
                      </div>
                      <ChevronRight size={14} className={cn('text-gray-600 shrink-0 transition-transform mt-1', isSelected && 'rotate-90')} />
                    </div>
                  </motion.button>
                );
              })}
            </AnimatePresence>
          </div>

          {/* Detail panel */}
          <AnimatePresence>
            {selected && (
              <motion.aside
                initial={{ opacity: 0, x: 20, width: 0 }}
                animate={{ opacity: 1, x: 0, width: 280 }}
                exit={{ opacity: 0, x: 20, width: 0 }}
                className="shrink-0 bg-gray-900 border border-gray-800 rounded-2xl p-4 overflow-hidden"
                style={{ minWidth: 240, maxWidth: 300 }}
              >
                <div className="flex items-center justify-between mb-4">
                  <p className="font-bold text-sm text-white">Incident Detail</p>
                  <button onClick={() => setSelected(null)} aria-label="Close detail panel"
                    className="w-7 h-7 rounded-xl bg-gray-800 flex items-center justify-center hover:bg-gray-700">
                    <X size={13} className="text-gray-400" />
                  </button>
                </div>

                <div className="space-y-3 text-xs">
                  <Row label="ID" value={selected.id.slice(0, 12) + '…'} />
                  <Row label="Type" value={selected.incident_type.replace('_', ' ')} />
                  <Row label="Status" value={STATUS_CONFIG[selected.status].label} valueClass={STATUS_CONFIG[selected.status].color} />
                  {selected.address && <Row label="Address" value={selected.address} />}
                  {selected.lat && <Row label="Coords" value={`${selected.lat.toFixed(5)}, ${selected.lng?.toFixed(5)}`} />}
                  {selected.battery_level != null && <Row label="Battery" value={`${selected.battery_level}%`} />}
                  {selected.responder_eta_minutes != null && <Row label="ETA" value={`${selected.responder_eta_minutes} min`} />}
                  <Row label="Created" value={new Date(selected.created_at).toLocaleTimeString()} />
                </div>

                {/* Live WebRTC distress stream */}
                {(selected.status === 'active' || selected.status === 'acknowledged') && (
                  <div className="mt-4 border border-red-500/30 rounded-2xl overflow-hidden bg-gray-950 aspect-video relative flex flex-col items-center justify-center shadow-[0_0_20px_rgba(220,38,38,0.15)]">

                    {remoteStream ? (
                      <video
                        ref={adminVideoRef}
                        autoPlay
                        playsInline
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <>
                        <div className="absolute inset-0 bg-cover bg-center opacity-40 filter blur-[2px]" style={{ backgroundImage: "url('https://images.unsplash.com/photo-1518386394876-0f8623b3f27a?w=400&q=80')" }} />

                        <div className="absolute bottom-2 left-2 right-2 flex items-end justify-between h-4 px-2 opacity-80 gap-0.5 z-10">
                          {[4, 10, 6, 8, 2, 9, 5, 7, 3, 11, 4, 8, 5, 10, 6, 2, 7, 3, 9, 5, 8].map((h, i) => (
                            <motion.span
                              key={i}
                              className="bg-red-500 w-full rounded-sm"
                              animate={{ height: [`${h * 1.5}px`, `${h * 0.4}px`, `${h * 1.5}px`] }}
                              transition={{ duration: 0.5 + i * 0.05, repeat: Infinity, ease: 'easeInOut' }}
                            />
                          ))}
                        </div>
                        <div className="z-10 flex flex-col items-center justify-center text-center p-3 space-y-1">
                          <div className="w-8 h-8 rounded-full border-2 border-red-500 border-t-transparent animate-spin mb-1" />
                          <p className="text-[10px] font-black text-white tracking-tight uppercase">
                            {webrtcConnected ? 'Waiting for video track...' : 'Connecting to distress feed...'}
                          </p>
                        </div>
                      </>
                    )}

                    <div className={cn("absolute top-2 left-2 text-white text-[9px] font-black px-2 py-0.5 rounded flex items-center gap-1.5 shadow", remoteStream ? 'bg-green-600' : 'bg-red-600')}>
                      <span className="w-1.5 h-1.5 bg-white rounded-full animate-ping" />
                      {remoteStream ? 'LIVE STREAM' : 'CONNECTING'}
                    </div>
                  </div>
                )}

                {/* Quick actions */}
                <div className="mt-4 space-y-2">
                  <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mb-2">Update Status</p>
                  {(['acknowledged', 'resolved', 'false_alarm'] as const)
                    .filter(s => s !== selected.status)
                    .map(s => {
                      const cfg = STATUS_CONFIG[s];
                      const Icon = cfg.icon;
                      return (
                        <button key={s}
                          disabled={updating === selected.id}
                          onClick={() => void handleStatusChange(selected, s)}
                          className={cn(
                            'w-full flex items-center gap-2 px-3 py-2 rounded-xl border text-xs font-semibold transition-all',
                            'bg-gray-800 border-gray-700 hover:border-gray-500 text-white',
                            updating === selected.id && 'opacity-50 cursor-wait'
                          )}
                        >
                          <Icon size={12} className={cfg.color} /> Mark {cfg.label}
                        </button>
                      );
                    })}
                  {/* Call & Navigate */}
                  <div className="flex gap-2 mt-3">
                    <a href="tel:112" aria-label="Call 112 emergency"
                      className="flex-1 flex items-center justify-center gap-1.5 py-2 rounded-xl bg-red-600 text-white text-xs font-bold">
                      <Phone size={12} /> 112
                    </a>
                    {selected.lat && (
                      <a href={`https://maps.google.com/?q=${selected.lat},${selected.lng}`}
                        target="_blank" rel="noreferrer" aria-label="Open location in Google Maps"
                        className="flex-1 flex items-center justify-center gap-1.5 py-2 rounded-xl bg-blue-600 text-white text-xs font-bold">
                        <MapPin size={12} /> Map
                      </a>
                    )}
                  </div>
                </div>
              </motion.aside>
            )}
          </AnimatePresence>
        </div>
      </div>
    </div>
  );
}

function Row({ label, value, valueClass = 'text-white' }: { label: string; value: string; valueClass?: string }) {
  return (
    <div className="flex justify-between gap-2">
      <span className="text-gray-500 shrink-0">{label}</span>
      <span className={cn('text-right break-all', valueClass)}>{value}</span>
    </div>
  );
}

import { google } from '@ai-sdk/google';
import { generateText } from 'ai';
import { NextRequest, NextResponse } from 'next/server';

export const runtime = 'edge';
export const maxDuration = 30;

export async function POST(req: NextRequest) {
  try {
    const apiKey = process.env.GOOGLE_GENERATIVE_AI_API_KEY;
    if (!apiKey) {
      return NextResponse.json({ error: 'Gemini API key not configured' }, { status: 503 });
    }

    const { query, center } = await req.json() as {
      query: string;
      center: { lat: number; lng: number };
    };

    if (!query) {
      return NextResponse.json({ error: 'Query parameter is required' }, { status: 400 });
    }

    const mapCenter = center || { lat: 28.6139, lng: 77.2090 }; // fallback: Delhi

    const systemPrompt = `You are a high-fidelity emergency location discovery AI on the ROADSoS platform.
The user is viewing the map at coordinates: latitude ${mapCenter.lat}, longitude ${mapCenter.lng}.
They are searching for: "${query}".

Based on your knowledge of actual clinics, hospitals, pharmacies, police stations, fire stations, or emergency services, return up to 5 matching facilities.
If the search is general (e.g., "Find nearest trauma center open now"), identify real facilities that would exist near those coordinates.
Since this is an emergency simulator, if you do not know the exact coordinates of facilities near this specific coordinate, generate highly realistic and accurate mock coordinates that are extremely close to the user (e.g., offset the user's current coordinates by a small random factor between -0.015 and +0.015) so they appear in their immediate vicinity on the map viewport.

You MUST respond with a JSON object containing a "places" key. The value of "places" must be an array of objects.
Do not output any markdown formatting, only valid raw JSON.

JSON Schema:
{
  "places": [
    {
      "name": "Full Facility Name",
      "lat": 12.34567, // latitude float
      "lng": 12.34567, // longitude float
      "address": "Street address, City",
      "phone": "Contact number (or emergency helpline if unknown)",
      "description": "Short explanation of why this was selected and what services it has (e.g., '24/7 Level 1 Trauma Center, Specialized in head injuries'). Keep it under 20 words.",
      "type": "hospitals" // Must be one of: "hospitals", "police", "fire", "pharmacy"
    }
  ]
}`;

    const { text } = await generateText({
      model: google('gemini-1.5-pro'),
      system: systemPrompt,
      prompt: `Find places matching "${query}" around coordinates ${mapCenter.lat}, ${mapCenter.lng}`,
      temperature: 0.2,
    });

    // Clean JSON response (strip markdown wrappers if model ignores instructions)
    let cleanText = text.trim();
    if (cleanText.startsWith('```json')) {
      cleanText = cleanText.substring(7);
    }
    if (cleanText.endsWith('```')) {
      cleanText = cleanText.substring(0, cleanText.length - 3);
    }
    cleanText = cleanText.trim();

    const parsed = JSON.parse(cleanText) as { places: any[] };
    return NextResponse.json(parsed);
  } catch (error: any) {
    console.error('[Gemini Map API] Error processing request:', error);
    return NextResponse.json({ error: error.message || 'Internal Server Error', places: [] }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { auth } from '@/auth';
import { createAdminClient } from '@/lib/supabase/client';

function generateUUID(input: string) {
  let hash = 0;
  for (let i = 0; i < input.length; i++) {
    hash = (hash << 5) - hash + input.charCodeAt(i);
    hash = hash & hash;
  }
  const hex = Math.abs(hash).toString(16).padStart(8, '0');
  return `${hex}-0000-4000-a000-000000000000`;
}

function ensureUUID(id: string, fallbackInput?: string | null) {
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  if (uuidRegex.test(id)) return id;
  return generateUUID(fallbackInput || id);
}

export async function GET(req: NextRequest) {
  const session = await auth();
  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const userId = ensureUUID(session.user.id, session.user.email);
  const adminDb = createAdminClient();
  if (!adminDb) {
    return NextResponse.json({ error: 'Database not configured' }, { status: 503 });
  }

  try {
    // 1. Get profile from public.profiles
    const { data: profile, error: profileError } = await adminDb
      .from('profiles')
      .select('*')
      .eq('id', userId)
      .single();

    if (profileError && profileError.code !== 'PGRST116') { // PGRST116 is "no rows found"
      return NextResponse.json({ error: profileError.message }, { status: 500 });
    }

    // 2. Get emergency contacts
    const { data: contacts, error: contactsError } = await adminDb
      .from('emergency_contacts')
      .select('*')
      .eq('user_id', userId)
      .order('created_at', { ascending: true });

    if (contactsError) {
      return NextResponse.json({ error: contactsError.message }, { status: 500 });
    }

    return NextResponse.json({
      profile: profile || null,
      contacts: contacts || []
    });
  } catch (err: any) {
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

export async function POST(req: NextRequest) {
  const session = await auth();
  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const userId = ensureUUID(session.user.id, session.user.email);
  const body = await req.json();
  const { name, phone, bloodGroup, conditions, allergies, address, contacts, dob } = body;

  const adminDb = createAdminClient();
  if (!adminDb) {
    return NextResponse.json({ error: 'Database not configured' }, { status: 503 });
  }

  try {
    // 1. Ensure user exists in auth.users first to satisfy foreign key constraints
    const { data: authUser, error: checkError } = await adminDb.auth.admin.getUserById(userId);

    if (checkError || !authUser?.user) {
      // User doesn't exist in auth.users, let's create them
      const { error: createError } = await adminDb.auth.admin.createUser({
        id: userId,
        email: session.user.email || undefined,
        email_confirm: true,
        user_metadata: {
          full_name: name || session.user.name || 'User',
          avatar_url: session.user.image || null
        },
        phone: phone || undefined
      });

      if (createError) {
        console.warn('[Profile API] Could not create auth user:', createError.message);
      }
    }

    // 2. Upsert user profile in public.profiles
    const parsedConditions = Array.isArray(conditions)
      ? conditions
      : typeof conditions === 'string'
        ? conditions.split(',').map(s => s.trim()).filter(Boolean)
        : [];

    const parsedAllergies = Array.isArray(allergies)
      ? allergies
      : typeof allergies === 'string'
        ? allergies.split(',').map(s => s.trim()).filter(Boolean)
        : [];

    const { error: userError } = await adminDb
      .from('profiles')
      .upsert({
        id: userId,
        name: name || session.user.name || 'User',
        phone: phone || null,
        medical_data: {
          blood_group: bloodGroup || 'Unknown',
          medical_conditions: parsedConditions,
          allergies: parsedAllergies,
          date_of_birth: dob || null,
          home_address: address || null,
        },
        updated_at: new Date().toISOString()
      });

    if (userError) {
      return NextResponse.json({ error: userError.message }, { status: 500 });
    }

    // 3. Update emergency contacts
    if (Array.isArray(contacts)) {
      // Delete existing contacts
      const { error: deleteError } = await adminDb
        .from('emergency_contacts')
        .delete()
        .eq('user_id', userId);

      if (deleteError) {
        return NextResponse.json({ error: deleteError.message }, { status: 500 });
      }

      // Insert new ones (if any)
      if (contacts.length > 0) {
        const contactsToInsert = contacts.map((c, index) => ({
          user_id: userId,
          name: c.name,
          phone: c.phone,
          relationship: c.relationship || c.relation || 'Emergency Contact',
          is_primary: index === 0
        }));

        const { error: contactsError } = await adminDb
          .from('emergency_contacts')
          .insert(contactsToInsert);

        if (contactsError) {
          return NextResponse.json({ error: contactsError.message }, { status: 500 });
        }
      }
    }

    return NextResponse.json({ success: true });
  } catch (err: any) {
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createAdminClient } from '@/lib/supabase/client';

export async function POST(req: NextRequest) {
  try {
    const { incidentId, contacts, userName } = await req.json();
    
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL ?? '';
    const supabaseConfigured = supabaseUrl.length > 0 && !supabaseUrl.includes('your-project');
    
    // 1. Update incident status in Supabase to 'resolved'
    if (supabaseConfigured) {
      try {
        const supabase = createAdminClient();
        if (supabase && incidentId) {
          await supabase
            .from('incidents')
            .update({ status: 'resolved', resolved_at: new Date().toISOString() })
            .eq('id', incidentId);
        }
      } catch (dbErr) {
        console.warn('[All Clear API] Database update error:', dbErr);
      }
    }
    
    // 2. Broadcast high-priority all-clear SMS via Twilio to emergency contacts
    const sid = process.env.TWILIO_SID || process.env.TWILIO_ACCOUNT_SID || '';
    const token = process.env.TWILIO_TOKEN || process.env.TWILIO_AUTH_TOKEN || '';
    const from = process.env.TWILIO_FROM || process.env.TWILIO_PHONE_NUMBER || '';
    
    const allClearMessage = `💚 ROADSoS Status Update 💚
${userName || 'User'} is now SAFE. The emergency incident has been resolved and marked ALL CLEAR. Thank you for your assistance.`;
    
    if (sid && token && from && Array.isArray(contacts) && contacts.length > 0) {
      const auth = Buffer.from(`${sid}:${token}`).toString('base64');
      const sendPromises = contacts.map(async (c: any) => {
        if (!c.phone) return;
        const res = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`, {
          method: 'POST',
          headers: {
            'Authorization': `Basic ${auth}`,
            'Content-Type': 'application/x-www-form-urlencoded'
          },
          body: new URLSearchParams({
            To: c.phone,
            From: from,
            Body: allClearMessage
          })
        });
        
        if (!res.ok) {
          const errData = await res.json();
          throw new Error(errData.message || `Failed to send to ${c.phone}`);
        }
        return res.json();
      });
      
      await Promise.allSettled(sendPromises);
    } else {
      console.warn('[All Clear API] Twilio variables or emergency contacts missing. Skipped sending resolution SMS.');
    }
    
    return NextResponse.json({
      success: true,
      message: 'All-clear event logged and contacts updated.'
    });
  } catch (err: any) {
    console.error('[All Clear API] Route error:', err);
    return NextResponse.json({ error: err.message || 'Internal All Clear API Error' }, { status: 500 });
  }
}

