                <CheckCircle2 size={32} />
              </div>
              <div className="space-y-1.5 max-w-sm">
                <h3 className="font-black text-white text-base">All clear — no active SOS feeds</h3>
                <p className="text-xs text-gray-500 leading-relaxed">
