    { href: '/directory', icon: Phone,         label: t('emergency.services', 'Emergency Numbers'),      desc: t('emergency.servicesDesc', 'Direct emergency lines'),          iconCls: 'text-violet-400',  bgCls: 'bg-violet-500/10'  },
