          {t('carMode.safetyWarning', '⚠️ Say "Hey Emergency" anytime for hand-free safety. Focus on driving.')}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-950 text-white pb-20">
