'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAutomotiveMode } from '@/hooks/useAutomotiveMode';
import { useSOSStore } from '@/lib/store/sosStore';
import { useChatStore } from '@/lib/store/chatStore';
import { useVoiceStore } from '@/lib/store/voiceStore';
import { useVoiceCommands } from '@/hooks/useVoiceCommands';
import { motion } from 'framer-motion';
import { 
  ShieldAlert, 
  Map, 
  Phone, 
  Mic, 
  Moon, 
  Sun, 
  Eye, 
  Navigation, 
  ArrowLeft,
  Activity
} from 'lucide-react';
import { cn } from '@/lib/utils';

export function AutomotiveLayout({ children }: { children: React.ReactNode }) {
  const { isAutomotive, toggleAutomotiveMode } = useAutomotiveMode();
  const armSOS = useSOSStore((s) => s.arm);
  const toggleChat = useChatStore((s) => s.toggle);
  const { startListening } = useVoiceCommands();
  const setOverlayOpen = useVoiceStore((s) => s.setOverlayOpen);
  const router = useRouter();

  // Speed and location tracking
  const [speed, setSpeed] = useState<number | null>(null);
  const [heading, setHeading] = useState<number | null>(null);
  const [positionError, setPositionError] = useState<string | null>(null);

  // Proximity status simulation/detection
  const [proximityNear, setProximityNear] = useState(false);

  // Ambient light / dimming
  const [lux, setLux] = useState<number | null>(null);
  const [isDimmed, setIsDimmed] = useState(false);

  useEffect(() => {
    if (!isAutomotive) return;

    // 1. Geolocation Speedometer
    let watchId: number;
    if (typeof window !== 'undefined' && 'geolocation' in navigator) {
      watchId = navigator.geolocation.watchPosition(
        (pos) => {
          // pos.coords.speed is in meters/second
          if (pos.coords.speed !== null) {
            // Convert to km/h
            setSpeed(Math.round(pos.coords.speed * 3.6));
          } else {
            setSpeed(null);
          }
          setHeading(pos.coords.heading);
          setPositionError(null);
        },
        (err) => {
          setPositionError(err.message);
        },
        { enableHighAccuracy: true }
      );
    }

    // 2. Ambient Light Sensor
    let ambientSensor: any = null;
    if (typeof window !== 'undefined' && 'AmbientLightSensor' in window) {
      try {
        const SensorClass = (window as any).AmbientLightSensor;
        ambientSensor = new SensorClass();
        ambientSensor.addEventListener('reading', () => {
          setLux(ambientSensor.lux);
          setIsDimmed(ambientSensor.lux < 10);
        });
        ambientSensor.start();
      } catch (err) {
        console.warn('AmbientLightSensor failed to initialize:', err);
      }
    }

    // Fallback: If no AmbientLightSensor, auto-dim during late night hours (7 PM - 7 AM)
    if (!ambientSensor) {
      const hours = new Date().getHours();
      setIsDimmed(hours >= 19 || hours < 7);
    }

    // 3. Proximity Sensor Simulation
    // Since DeviceProximityEvent is deprecated, we simulate it or watch UserProximity if available
    const handleUserProximity = (event: any) => {
      setProximityNear(event.near);
    };
    window.addEventListener('userproximity' as any, handleUserProximity);

    return () => {
      if (watchId) navigator.geolocation.clearWatch(watchId);
      if (ambientSensor) {
        try {
          ambientSensor.stop();
        } catch {}
      }
      window.removeEventListener('userproximity' as any, handleUserProximity);
    };
  }, [isAutomotive]);

  if (!isAutomotive) {
    return <>{children}</>;
  }

  // Convert Heading degrees to Compass directions
  const getCompassDirection = (deg: number | null) => {
    if (deg === null) return 'N';
    const directions = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
    const idx = Math.round(((deg % 360) / 45)) % 8;
    return directions[idx];
  };

  const handleSOSClick = () => {
    // Instant arm in automotive mode
    armSOS('manual', 5);
  };

  const handleVoiceAssistantClick = () => {
    // Enable continuous listening & open command list for visual guidance
    startListening();
    setOverlayOpen(true);
  };

  return (
    <div 
      className={cn(
        "fixed inset-0 z-[9999] flex flex-row overflow-hidden transition-colors duration-500 font-sans select-none",
        isDimmed 
          ? "bg-black text-red-500" // Night view / vision preservation
          : "bg-black text-white"   // Normal high-contrast CarPlay mode
      )}
    >
      {/* LEFT SIDEBAR: Huge CarPlay Action Buttons (min 64px tap target, 24px gaps) */}
      <div 
        className={cn(
          "w-1/3 max-w-[280px] h-full flex flex-col p-6 gap-6 justify-between shrink-0 border-r",
          isDimmed ? "border-red-950 bg-black" : "border-gray-900 bg-gray-950"
        )}
      >
        {/* Top Header - App ID & Mode Switcher */}
        <div className="flex items-center justify-between">
          <span className="text-xs font-black tracking-widest uppercase flex items-center gap-2">
            <Activity size={14} className="text-red-500 animate-pulse" />
            RoadSOS Auto
          </span>
          <button
            onClick={toggleAutomotiveMode}
            className="p-3 rounded-xl bg-gray-950 border border-gray-800 text-[10px] uppercase font-bold text-gray-400 hover:text-white flex items-center gap-1.5"
          >
            <ArrowLeft size={10} /> Exit
          </button>
        </div>

        {/* Action Buttons Grid */}
        <div className="flex-1 flex flex-col justify-center gap-5">
          {/* Button 1: SOS (Huge, red pulsing) */}
          <motion.button
            onClick={handleSOSClick}
            whileTap={{ scale: 0.95 }}
            className="w-full h-16 rounded-2xl bg-red-600 border border-red-500 text-white font-black uppercase text-sm tracking-wide flex items-center justify-center gap-3 shadow-lg shadow-red-900/20 active:bg-red-700"
          >
            <ShieldAlert size={24} className="animate-pulse" />
            Trigger SOS
          </motion.button>

          {/* Button 2: Map */}
          <motion.button
            onClick={() => router.push('/map')}
            whileTap={{ scale: 0.95 }}
            className={cn(
              "w-full h-16 rounded-2xl font-black uppercase text-sm tracking-wide flex items-center justify-center gap-3 border shadow-md",
              isDimmed 
                ? "bg-red-950/20 border-red-900 text-red-500" 
                : "bg-gray-900 border-gray-800 text-white hover:bg-gray-850"
            )}
          >
            <Map size={24} />
            Show Map
          </motion.button>

          {/* Button 3: Call Ambulance */}
          <motion.button
            onClick={() => { window.location.href = 'tel:108'; }}
            whileTap={{ scale: 0.95 }}
            className={cn(
              "w-full h-16 rounded-2xl font-black uppercase text-sm tracking-wide flex items-center justify-center gap-3 border shadow-md",
              isDimmed 
                ? "bg-red-950/30 border-red-900 text-red-400" 
                : "bg-blue-900/30 border-blue-800 text-blue-400 hover:bg-blue-900/40"
            )}
          >
            <Phone size={24} />
            Call Ambulance
          </motion.button>

          {/* Button 4: AI Voice Assistant */}
          <motion.button
            onClick={handleVoiceAssistantClick}
            whileTap={{ scale: 0.95 }}
            className={cn(
              "w-full h-16 rounded-2xl font-black uppercase text-sm tracking-wide flex items-center justify-center gap-3 border shadow-md",
              isDimmed 
                ? "bg-red-950/30 border-red-900 text-red-400" 
                : "bg-purple-900/30 border-purple-800 text-purple-400 hover:bg-purple-900/40"
            )}
          >
            <Mic size={24} className="animate-bounce" />
            Voice Helper
          </motion.button>
        </div>

        {/* Footer Dim Mode Indicator */}
        <div className="flex items-center justify-between text-[10px] text-gray-500 font-bold tracking-wider">
          <div className="flex items-center gap-1.5">
            {isDimmed ? <Moon size={12} className="text-amber-500" /> : <Sun size={12} className="text-yellow-500" />}
            <span>{isDimmed ? 'NIGHT SCREEN' : 'DAY SCREEN'}</span>
          </div>
          <span>{lux !== null ? `${lux} LX` : 'AUTO LUX'}</span>
        </div>
      </div>

      {/* RIGHT MAIN VIEW: Speed, Proximity, Navigation */}
      <div className="flex-1 h-full flex flex-col p-8 justify-between relative">
        {/* Speed / Dashboard Section */}
        <div className="grid grid-cols-3 gap-6 flex-1 items-center">

          {/* Dashboard Item 1: Live Speedometer */}
          <div className="flex flex-col items-center justify-center">
            <span className="text-[10px] font-black uppercase tracking-widest text-gray-400">Speed</span>
            <div className="text-7xl font-black font-mono tracking-tighter text-white tabular-nums my-1">
              {speed !== null ? speed : '0'}
            </div>
            <span className="text-xs font-bold text-gray-400 uppercase">KM/H</span>
          </div>

          {/* Dashboard Item 2: Heading / Direction */}
          <div className="flex flex-col items-center justify-center border-x border-gray-900 py-4">
            <span className="text-[10px] font-black uppercase tracking-widest text-gray-400">Direction</span>
            <div className="text-6xl font-black font-mono text-white my-2 flex items-center gap-1">
              <Navigation 
                size={28} 
                className="text-red-500" 
                style={{ transform: `rotate(${heading ?? 0}deg)` }}
              />
              {getCompassDirection(heading)}
            </div>
            <span className="text-xs font-bold text-gray-400 uppercase">{heading !== null ? `${Math.round(heading)}°` : '0°'}</span>
          </div>

          {/* Dashboard Item 3: Proximity Sensor / Safety */}
          <div className="flex flex-col items-center justify-center">
            <span className="text-[10px] font-black uppercase tracking-widest text-gray-400">Proximity</span>
            <div 
              className={cn(
                "my-3 px-4 py-2 rounded-xl text-xs font-black uppercase tracking-wider flex items-center gap-2 border",
                proximityNear 
                  ? "bg-red-500/20 border-red-500 text-red-400 animate-pulse" 
                  : "bg-emerald-500/10 border-emerald-500/20 text-emerald-400"
              )}
            >
              <Eye size={16} />
              {proximityNear ? 'OBSTACLE DETECTED' : 'PATH CLEAR'}
            </div>
            <span className="text-[9px] font-semibold text-gray-500 text-center leading-normal max-w-[120px]">
              {proximityNear ? 'Move device clear of windshield mount' : 'Device orientation and sensors calibrated'}
            </span>
          </div>
        </div>

        {/* Navigation / Instructions Section */}
        <div 
          className={cn(
            "rounded-2xl p-5 flex items-center justify-between border shadow-sm",
            isDimmed 
              ? "bg-red-950/10 border-red-900/30" 
              : "bg-gray-950 border-gray-900"
          )}
        >
          <div className="space-y-1">
            <h3 className="text-sm font-black uppercase tracking-wide text-white">CarPlay System Online</h3>
            <p className="text-[11px] text-gray-400 leading-normal max-w-lg">
              Automotive navigation layers are loaded. Say <strong className="text-white">"Hey Emergency"</strong> at any time to execute instant safety commands hands-free while driving.
            </p>
          </div>
          <div className="text-right">
            <span className="text-[10px] font-black text-red-500 bg-red-500/10 border border-red-500/20 px-3 py-1.5 rounded-full uppercase tracking-wider">
              System Active
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  MessageSquare,
  MessageCircle,
  Mail,
  Bell,
  Bluetooth,
  Cpu,
  Database,
  Radio,
  CheckCircle2,
  XCircle,
  AlertCircle,
  Loader2
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useSOSStore, BroadcastStatus } from '@/lib/store/sosStore';

interface BroadcastPanelProps {
  onContinue: () => void;
}

const CHANNEL_CONFIG = {
  sms: { label: 'Twilio SMS Dispatch', icon: MessageSquare, desc: 'Direct secure SMS to emergency contacts' },
  whatsapp: { label: 'WhatsApp Deep Link', icon: MessageCircle, desc: 'Pre-populated WhatsApp message link' },
  email: { label: 'Resend HTML Email', icon: Mail, desc: 'High-accuracy bento-grid email report' },
  push: { label: 'Web Push Service', icon: Bell, desc: 'Real-time alert on contact devices' },
  bluetooth: { label: 'Web Bluetooth Beacon', icon: Bluetooth, desc: 'Hardware SOS packet advertisement' },
  serial: { label: 'Web Serial COM Sweeper', icon: Cpu, desc: 'Emergency broadcast string to transceivers' },
  websocket: { label: 'Supabase Realtime', icon: Database, desc: 'Pushes live incident coordinate pins' },
  mqtt: { label: 'HiveMQ Public Broker', icon: Radio, desc: 'MQTT secure topic pub/sub transmission' }
};

export function BroadcastPanel({ onContinue }: BroadcastPanelProps) {
  const { t } = useTranslation();
  const { broadcastStatus } = useSOSStore();
  const [resolvedChannels, setResolvedChannels] = useState<string[]>([]);
  const autoDismissTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const sineWaveRef = useRef<SVGPathElement | null>(null);

  // Parse the current broadcast status
  const currentStatus = broadcastStatus || {
    sms: 'pending',
    whatsapp: 'pending',
    email: 'pending',
    push: 'pending',
    bluetooth: 'pending',
    serial: 'pending',
    websocket: 'pending',
    mqtt: 'pending'
  };

  const channelKeys = Object.keys(CHANNEL_CONFIG) as (keyof typeof CHANNEL_CONFIG)[];

  // Track how many channels are completed/resolved
  const allResolved = channelKeys.every((k) => currentStatus[k] !== 'pending');

  // Trigger auto-dismiss when all resolve
  useEffect(() => {
    if (allResolved) {
      autoDismissTimerRef.current = setTimeout(() => {
        onContinue();
      }, 8000);
    }
    return () => {
      if (autoDismissTimerRef.current) {
        clearTimeout(autoDismissTimerRef.current);
      }
    };
  }, [allResolved, onContinue]);

  // Frequency Sweep Sine Wave Animation
  useEffect(() => {
    let animationFrameId: number;
    let phase = 0;

    const animateWave = () => {
      phase += 0.15;
      if (sineWaveRef.current) {
        let points = [];
        const width = 300;
        const height = 40;
        for (let x = 0; x <= width; x += 2) {
          // Alter frequency and amplitude to simulate sweeping through bandwidths
          const freq = 0.04 + Math.sin(phase * 0.2) * 0.02;
          const amp = 10 + Math.sin(phase * 0.1) * 6;
          const y = height / 2 + Math.sin(x * freq + phase) * amp;
          points.push(`${x},${y}`);
        }
        sineWaveRef.current.setAttribute('d', `M ${points.join(' L ')}`);
      }
      animationFrameId = requestAnimationFrame(animateWave);
    };

    animateWave();
    return () => cancelAnimationFrame(animationFrameId);
  }, []);

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'sent':
      case 'broadcast':
      case 'link_generated':
      case 'published':
      case 'connected':
        return <CheckCircle2 className="w-5 h-5 text-green-400 drop-shadow-[0_0_8px_rgba(74,222,128,0.5)]" />;
      case 'failed':
        return <XCircle className="w-5 h-5 text-red-500 drop-shadow-[0_0_8px_rgba(239,68,68,0.5)]" />;
      case 'unavailable':
        return <AlertCircle className="w-5 h-5 text-gray-500" />;
      case 'pending':
      default:
        return <Loader2 className="w-5 h-5 text-red-500 animate-spin" />;
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case 'sent':
      case 'broadcast':
      case 'link_generated':
      case 'published':
      case 'connected':
        return t('sos.sent', 'Sent');
      case 'failed':
        return t('sos.failed', 'Failed');
      case 'unavailable':
        return t('sos.unavailable', 'Unavailable');
      case 'pending':
      default:
        return t('sos.transmitting', 'Transmitting...');
    }
  };

  return (
    <div className="fixed inset-0 z-[120] flex flex-col items-center justify-center bg-gray-950/96 backdrop-blur-xl p-6 text-white overflow-y-auto">
      <div className="w-full max-w-md bg-gray-900/80 border border-gray-800 rounded-3xl p-6 shadow-2xl relative overflow-hidden">
        {/* Animated Sweep Ambient Light */}
        <div className="absolute -top-24 -left-24 w-48 h-48 bg-red-600/10 rounded-full blur-3xl pointer-events-none" />
        <div className="absolute -bottom-24 -right-24 w-48 h-48 bg-red-600/10 rounded-full blur-3xl pointer-events-none" />

        {/* Frequency Sweep Header */}
        <div className="flex flex-col items-center border-b border-gray-800/60 pb-6 mb-6">
          <div className="w-full max-w-[300px] h-[50px] flex items-center justify-center bg-black/40 rounded-2xl mb-4 border border-gray-800/40 relative">
            <svg className="w-full h-full" viewBox="0 0 300 40">
              <path
                ref={sineWaveRef}
                fill="none"
                stroke="url(#glowing-red)"
                strokeWidth="2.5"
                strokeLinecap="round"
              />
              <defs>
                <linearGradient id="glowing-red" x1="0%" y1="0%" x2="100%" y2="0%">
                  <stop offset="0%" stopColor="#7f1d1d" />
                  <stop offset="50%" stopColor="#ef4444" />
                  <stop offset="100%" stopColor="#7f1d1d" />
                </linearGradient>
              </defs>
            </svg>
            <span className="absolute text-[8px] font-black tracking-widest text-red-500/80 uppercase bottom-1">
              {t('sos.frequencySweep', 'Frequency Sweep Active')}
            </span>
          </div>

          <h2 className="text-white font-black text-xl tracking-tight text-center">
            {t('sos.broadcastingDistress', 'Broadcasting Distress Signals')}
          </h2>
          <p className="text-gray-400 text-xs mt-1.5 text-center px-4">
            {t('sos.allChannelsActive', 'Emitting distress packets through all wireless and IP channels simultaneously')}
          </p>
        </div>

        {/* 8 Channel Transmission Status List */}
        <div className="space-y-3.5 max-h-[360px] overflow-y-auto pr-1 no-scrollbar">
          {channelKeys.map((key) => {
            const config = CHANNEL_CONFIG[key];
            const Icon = config.icon;
            const stat = currentStatus[key];
            
            return (
              <div
                key={key}
                className="flex items-center justify-between bg-black/30 border border-gray-800/40 rounded-2xl p-3 hover:border-gray-800 transition-colors"
              >
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-xl flex items-center justify-center bg-gray-800/50 border border-gray-700/30">
                    <Icon className="w-4 h-4 text-red-400" />
                  </div>
                  <div>
                    <h3 className="text-xs font-black text-white tracking-tight">{config.label}</h3>
                    <p className="text-[10px] text-gray-500 font-medium leading-none mt-0.5">{config.desc}</p>
                  </div>
                </div>
                
                <div className="flex items-center gap-2">
                  <span className="text-[9px] font-bold text-gray-400 uppercase tracking-widest">
                    {getStatusText(stat)}
                  </span>
                  {getStatusIcon(stat)}
                </div>
              </div>
            );
          })}
        </div>

        {/* Bottom Interactive Zone */}
        <div className="mt-6 pt-4 border-t border-gray-800/60 flex flex-col items-center">
          <AnimatePresence mode="wait">
            {allResolved ? (
              <motion.button
                key="btn-continue"
                initial={{ opacity: 0, y: 15 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -15 }}
                onClick={onContinue}
                className="w-full bg-red-600 hover:bg-red-700 text-white font-black text-sm tracking-widest uppercase rounded-2xl py-4 shadow-[0_0_25px_rgba(239,68,68,0.4)] transition-all flex items-center justify-center gap-2 active:scale-98 cursor-pointer"
              >
                <span>{t('buttons.continue', 'Continue to Dashboard')}</span>
              </motion.button>
            ) : (
              <motion.div
                key="loading-msg"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="flex items-center gap-2 py-2"
              >
                <Loader2 className="w-4 h-4 text-red-500 animate-spin" />
                <span className="text-[11px] font-bold text-gray-500 uppercase tracking-wider">
                  {t('sos.waitingForChannels', 'Synthesizing channel outcomes...')}
                </span>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </div>
  );
}

