                scaledSize: new google.maps.Size(32, 32),
              }}
              label={{ text: '🚑', fontSize: '15px' }}
            />
          )}
        </GoogleMap>
      </main>
    </div>
  );
}

'use client';

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { useTheme } from 'next-themes';
import { motion, AnimatePresence } from 'framer-motion';
import { Globe, Sun, Moon, Laptop, Check, Bell } from 'lucide-react';
import { cn } from '@/lib/utils';

interface Language {
  code: string;
  name: string;
  flag: string;
}

const LANGUAGES: Language[] = [
  { code: 'en', name: 'English', flag: '🇺🇸' },
  { code: 'hi', name: 'हिंदी', flag: '🇮🇳' },
  { code: 'gu', name: 'ગુજરાતી', flag: '🇮🇳' },
  { code: 'es', name: 'Español', flag: '🇪🇸' },
  { code: 'fr', name: 'Français', flag: '🇫🇷' },
  { code: 'ar', name: 'العربية', flag: '🇸🇦' },
  { code: 'pt', name: 'Português', flag: '🇵🇹' },
  { code: 'zh', name: '简体中文', flag: '🇨🇳' },
  { code: 'bn', name: 'বাংলা', flag: '🇧🇩' },
  { code: 'ru', name: 'Русский', flag: '🇷🇺' }
];

export function HeaderControls() {
  const { i18n } = useTranslation();
  const { theme, setTheme, resolvedTheme } = useTheme();
  const [dropdownOpen, setDropdownOpen] = React.useState(false);
  const dropdownRef = React.useRef<HTMLDivElement>(null);

  // Close dropdown on click outside
  React.useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setDropdownOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const currentLang = LANGUAGES.find(l => l.code === i18n.language) || LANGUAGES[0];

  const handleLanguageChange = (code: string) => {
    void i18n.changeLanguage(code);
    setDropdownOpen(false);
  };

  // Cycle theme: light -> dark -> system -> light
  const toggleTheme = () => {
    if (theme === 'light') {
      setTheme('dark');
    } else if (theme === 'dark') {
      setTheme('system');
    } else {
      setTheme('light');
    }
  };

  const renderThemeIcon = () => {
    if (theme === 'light') return <Sun size={18} className="text-amber-400 rotate-0 transition-transform duration-300" />;
    if (theme === 'dark') return <Moon size={18} className="text-indigo-400 rotate-0 transition-transform duration-300" />;
    return <Laptop size={18} className="text-teal-400 transition-transform duration-300" />;
  };

  return (
    <div className="flex items-center gap-1.5 relative z-50">
      {/* Notifications Button */}
      <button
        onClick={() => {
          if ('Notification' in window) {
            Notification.requestPermission();
          }
        }}
        aria-label="Push Notifications"
        className="w-9 h-9 rounded-xl flex items-center justify-center bg-gray-900/60 border border-gray-800/80 text-gray-400 hover:text-white hover:border-gray-700/80 active:scale-95 transition-all shadow-sm"
      >
        <Bell size={16} className="text-blue-400" />
      </button>

      {/* Quick Theme Toggle Button */}
      <button
        onClick={toggleTheme}
        aria-label={`Cycle theme, current: ${theme}`}
        className="w-9 h-9 rounded-xl flex items-center justify-center bg-gray-900/60 border border-gray-800/80 text-gray-400 hover:text-white hover:border-gray-700/80 active:scale-95 transition-all shadow-sm"
      >
        {renderThemeIcon()}
      </button>

      {/* Language Globe Button */}
      <div className="relative" ref={dropdownRef}>
        <button
          onClick={() => setDropdownOpen(!dropdownOpen)}
          aria-expanded={dropdownOpen}
          aria-label="Select language"
          className={cn(
            "h-9 px-2.5 gap-1.5 rounded-xl flex items-center justify-center bg-gray-900/60 border border-gray-800/80 text-gray-400 hover:text-white hover:border-gray-700/80 active:scale-95 transition-all shadow-sm",
            dropdownOpen && "border-red-500/50 text-white bg-gray-900"
          )}
        >
          <Globe size={16} className={cn("transition-transform duration-300", dropdownOpen && "rotate-45 text-red-400")} />
          <span className="text-xs font-bold uppercase tracking-tight hidden xs:inline">
            {currentLang.code}
          </span>
          <span className="text-xs">{currentLang.flag}</span>
        </button>

        {/* Dropdown Menu */}
        <AnimatePresence>
          {dropdownOpen && (
            <motion.div
              initial={{ opacity: 0, y: 8, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 8, scale: 0.95 }}
              transition={{ duration: 0.15, ease: 'easeOut' }}
              className="absolute right-0 mt-2 w-56 rounded-2xl bg-gray-950 border border-gray-800/90 shadow-2xl p-1.5 divide-y divide-gray-900 max-h-[350px] overflow-y-auto no-scrollbar"
            >
              <div className="py-1">
                {LANGUAGES.map((lang) => {
                  const active = i18n.language === lang.code;
                  return (
                    <button
                      key={lang.code}
                      onClick={() => handleLanguageChange(lang.code)}
                      className={cn(
                        "w-full flex items-center justify-between px-3 py-2 rounded-xl text-left text-sm font-medium transition-all",
                        active 
                          ? "bg-red-950/20 text-red-400 border border-red-900/20" 
                          : "text-gray-400 hover:text-white hover:bg-gray-900/60 border border-transparent"
                      )}
                    >
                      <div className="flex items-center gap-2.5">
                        <span className="text-base select-none" role="img" aria-label={`${lang.name} flag`}>
                          {lang.flag}
                        </span>
                        <span className="font-semibold tracking-tight leading-none">
                          {lang.name}
                        </span>
                      </div>
                      {active && (
                        <Check size={14} className="text-red-400" />
                      )}
                    </button>
                  );
                })}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useRef, useCallback } from 'react';
import { useSOSStore } from '@/lib/store/sosStore';
import { toast } from 'sonner';

export function SensorWatcher() {
  const { status, arm } = useSOSStore();
  const highAccelStartRef = useRef<number>(0);
  const lastHighAccelRef = useRef<number>(0);
  const isCountingDownRef = useRef<boolean>(false);
  const countdownIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const triggerShakeFlow = useCallback(() => {
    if (status !== 'idle' || isCountingDownRef.current) return;
    isCountingDownRef.current = true;

    let secondsLeft = 5;
    const toastId = toast.info(`Shake detected — SOS in 5s`, {
      action: {
        label: 'Cancel',
        onClick: () => {
          if (countdownIntervalRef.current) {
            clearInterval(countdownIntervalRef.current);
          }
          isCountingDownRef.current = false;
          toast.dismiss(toastId);
          toast.success('SOS cancelled');
        }
      },
      duration: Infinity
    });

    countdownIntervalRef.current = setInterval(() => {
      secondsLeft -= 1;
      if (secondsLeft <= 0) {
        if (countdownIntervalRef.current) {
          clearInterval(countdownIntervalRef.current);
        }
        isCountingDownRef.current = false;
        toast.dismiss(toastId);
        arm('shake');
      } else {
        toast.info(`Shake detected — SOS in ${secondsLeft}s`, {
          id: toastId,
          action: {
            label: 'Cancel',
            onClick: () => {
              if (countdownIntervalRef.current) {
                clearInterval(countdownIntervalRef.current);
              }
              isCountingDownRef.current = false;
              toast.dismiss(toastId);
              toast.success('SOS cancelled');
            }
          },
          duration: Infinity
        });
      }
    }, 1000);
  }, [status, arm]);

  const handleMotion = useCallback(
    (e: DeviceMotionEvent) => {
      if (status !== 'idle') return;

      const acc = e.acceleration || e.accelerationIncludingGravity;
      if (!acc) return;

      const x = acc.x ?? 0;
      const y = acc.y ?? 0;
      const z = acc.z ?? 0;

      const magnitude = Math.sqrt(x * x + y * y + z * z);

      // Sudden stop / Crash: >40 m/s^2
      if (magnitude > 40) {
        console.warn(`[SensorWatcher] Sudden stop / Crash detected: ${magnitude.toFixed(2)} m/s²`);
        toast.error('Crash detected! Initiating emergency broadcast...', { duration: 5000 });
        if (countdownIntervalRef.current) {
          clearInterval(countdownIntervalRef.current);
        }
        isCountingDownRef.current = false;
        arm('crash');
        return;
      }

      // Shake: >25 m/s^2 sustained for 500ms
      if (magnitude > 25) {
        const now = Date.now();
        if (highAccelStartRef.current === 0) {
          highAccelStartRef.current = now;
        }
        lastHighAccelRef.current = now;

        if (now - highAccelStartRef.current >= 500) {
          highAccelStartRef.current = 0; // reset
          triggerShakeFlow();
        }
      } else {
        if (Date.now() - lastHighAccelRef.current > 100) {
          highAccelStartRef.current = 0;
        }
      }
    },
    [status, arm, triggerShakeFlow]
  );

  const handleOrientation = useCallback((e: DeviceOrientationEvent) => {
    if (status !== 'idle') return;
    const { beta, gamma } = e;
    if (beta === null || gamma === null) return;

    // Rollover: phone tilted > 120 deg
    if (Math.abs(beta) > 120 || Math.abs(gamma) > 120) {
      console.warn(`[SensorWatcher] Rollover detected: beta=${beta.toFixed(0)}, gamma=${gamma.toFixed(0)}`);
      arm('rollover', 15);
    }
  }, [status, arm]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const requestPermissions = async () => {
      if (typeof (DeviceMotionEvent as any).requestPermission === 'function') {
        try {
          const permissionState = await (DeviceMotionEvent as any).requestPermission();
          if (permissionState === 'granted') {
            window.addEventListener('devicemotion', handleMotion);
            window.addEventListener('deviceorientation', handleOrientation);
          }
        } catch (e) {
          console.error('[SensorWatcher] Permission request failed', e);
        }
      } else {
        window.addEventListener('devicemotion', handleMotion);
        window.addEventListener('deviceorientation', handleOrientation);
      }
    };

    requestPermissions();

    return () => {
      window.removeEventListener('devicemotion', handleMotion);
      window.removeEventListener('deviceorientation', handleOrientation);
      if (countdownIntervalRef.current) {
        clearInterval(countdownIntervalRef.current);
      }
    };
  }, [handleMotion, handleOrientation]);

  return null;
}

