'use client';

import { useEffect, useRef, useCallback, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useSOSStore } from '@/lib/store/sosStore';
import { useWebRTC, startEmergencyStream } from '@/lib/webrtc';
import { useTranslation } from 'react-i18next';
import { useSession } from 'next-auth/react';
import { LiveStreamPanel } from '../LiveStreamPanel';
import {
  X,
  MapPin,
  Radio,
  Siren,
  Clock,
  Camera,
  CameraOff,
  Mic,
  MicOff,
  Terminal as TerminalIcon,
  Video,
  Volume2,
  ShieldAlert,
  Truck,
  Compass,
  Loader2
} from 'lucide-react';
import { GoogleMap, useJsApiLoader, Marker, DirectionsRenderer } from '@react-google-maps/api';
import { getBrowserClient } from '@/lib/supabase/browser';
import { BroadcastPanel } from '../BroadcastPanel';
import { cn } from '@/lib/utils';

const LIBRARIES: ('places' | 'visualization' | 'geometry')[] = ['places', 'visualization', 'geometry'];

const DARK_MAP_STYLE = [
  { elementType: 'geometry', stylers: [{ color: '#0f0f0f' }] },
  { elementType: 'labels.text.fill', stylers: [{ color: '#8ec3b9' }] },
  { featureType: 'road', elementType: 'geometry', stylers: [{ color: '#1c1c1c' }] },
  { featureType: 'road.arterial', elementType: 'geometry', stylers: [{ color: '#222' }] },
  { featureType: 'water', elementType: 'geometry', stylers: [{ color: '#001f3f' }] },
  { featureType: 'poi', stylers: [{ visibility: 'off' }] },
];

export function PanicMode() {
  const {
    status,
    countdownSeconds,
    location,
    broadcastStatus,
    responder,
    cancel,
    tickCountdown,
    resolve,
    allClear,
    autoDialed,
    setAutoDialed,
    incidentId,
  } = useSOSStore();
  const { t } = useTranslation();

  const { isLoaded } = useJsApiLoader({
    googleMapsApiKey: process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY || '',
    libraries: LIBRARIES as any,
  });

  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);

  const { data: session } = useSession();
  const userId = session?.user?.email || 'guest_user';

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [activeStream, setActiveStream] = useState<MediaStream | null>(null);
  const [activePeers, setActivePeers] = useState<Record<string, any>>({});
  const stopFnRef = useRef<(() => void) | null>(null);
  const [streamError, setStreamError] = useState<string | null>(null);
  const [cameraOn, setCameraOn] = useState(true);
  const [micOn, setMicOn] = useState(true);
  const [terminalLogs, setTerminalLogs] = useState<string[]>([]);
  const [showBroadcast, setShowBroadcast] = useState(false);
  const [flashToggle, setFlashToggle] = useState(false);

  // Responder & directions state
  const [responderInfo, setResponderInfo] = useState<{
    name: string;
    lat: number;
    lng: number;
  } | null>(null);
  const [directionsResponse, setDirectionsResponse] = useState<google.maps.DirectionsResult | null>(null);
  const [liveDistance, setLiveDistance] = useState<string | null>(null);
  const [liveDuration, setLiveDuration] = useState<string | null>(null);

  // Log append helper
  const addLog = useCallback((msg: string) => {
    setTerminalLogs((prev) => [
      ...prev.slice(-5),
      `[${new Date().toLocaleTimeString()}] ${msg}`
    ]);
  }, []);

  // Countdown ticker & flash effect
  useEffect(() => {
    if (status === 'countdown') {
      intervalRef.current = setInterval(tickCountdown, 1000);
      addLog(`Countdown active: ${countdownSeconds}s remaining...`);

      const flashId = setInterval(() => {
        setFlashToggle((prev) => !prev);
      }, 350);
      return () => {
        if (intervalRef.current) clearInterval(intervalRef.current);
        clearInterval(flashId);
      };
    } else {
      if (intervalRef.current) clearInterval(intervalRef.current);
      setFlashToggle(false);
    }
  }, [status, tickCountdown, countdownSeconds, addLog]);

  // Set showBroadcast overlay when SOS active state is reached
  useEffect(() => {
    if (status === 'active') {
      setShowBroadcast(true);
    }
  }, [status]);

  // Siren audio oscillation
  const playSiren = useCallback(() => {
    if (typeof window === 'undefined') return;
    try {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioContextClass) return;
      const ctx = new AudioContextClass();
      audioCtxRef.current = ctx;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.type = 'sawtooth';
      gain.gain.value = 0.15; // Low volume for safety

      // Wobbling siren frequency
      osc.frequency.setValueAtTime(800, ctx.currentTime);
      osc.frequency.linearRampToValueAtTime(500, ctx.currentTime + 0.4);
      osc.frequency.linearRampToValueAtTime(800, ctx.currentTime + 0.8);

      osc.start();
      osc.stop(ctx.currentTime + 0.8);
    } catch (e) {
      console.warn('Siren audio error:', e);
    }
  }, []);

  // Pulse siren & vibration
  useEffect(() => {
    if (status === 'active' || status === 'acknowledged' || status === 'countdown') {
      const id = setInterval(playSiren, 1000);
      if (typeof navigator !== 'undefined' && navigator.vibrate) {
        navigator.vibrate([300, 100, 300, 100, 500]);
      }
      return () => clearInterval(id);
    }
  }, [status, playSiren]);

  // WebRTC User Media Capture & Emergency Stream Broker
  useEffect(() => {
    if (status === 'active' || status === 'acknowledged') {
      addLog('WebRTC: Accessing camera and microphone...');

      let stopped = false;

      const startStream = async () => {
        try {
          const res = await startEmergencyStream(userId, incidentId || 'default-sos');

          if (stopped) {
            res.stop();
            return;
          }

          setActiveStream(res.stream);
          setActivePeers(res.peers);
          stopFnRef.current = res.stop;

          if (res.stream) {
            setStream(res.stream);
            setStreamError(null);
            const hasVideo = res.stream.getVideoTracks().length > 0;
            const hasAudio = res.stream.getAudioTracks().length > 0;
            setCameraOn(hasVideo);
            setMicOn(hasAudio);

            if (hasVideo) {
              addLog('WebRTC: Emergency video stream active.');
            } else if (hasAudio) {
              addLog('WebRTC: Camera blocked — emergency audio stream active.');
              setStreamError('Video blocked — streaming audio only');
            } else {
              setStreamError('Permissions blocked — location telemetry only');
            }

            if (videoRef.current) {
              videoRef.current.srcObject = res.stream;
            }
          } else {
            setStream(null);
            setStreamError('Permissions blocked — location telemetry only');
            addLog('WebRTC: Media disabled by user/system permissions.');
          }
        } catch (err: any) {
          console.error('[PanicMode] Emergency stream start failed:', err);
          setStreamError('Stream initialization error');
          addLog(`WebRTC: Stream error: ${err.message || err}`);
        }
      };

      void startStream();

      return () => {
        stopped = true;
        if (stopFnRef.current) {
          stopFnRef.current();
          stopFnRef.current = null;
        }
        setActiveStream(null);
        setActivePeers({});
        setStream(null);
        addLog('WebRTC: Emergency stream stopped.');
      };
    } else {
      if (stopFnRef.current) {
        stopFnRef.current();
        stopFnRef.current = null;
      }
      setActiveStream(null);
      setActivePeers({});
      setStream(null);
      setStreamError(null);
    }
  }, [status, userId, incidentId, addLog]);

  // Hook up simple-peer WebRTC via Supabase Broadcast
  const { connected: webrtcConnected } = useWebRTC(
    useSOSStore.getState().incidentId,
    'victim',
    stream
  );

  useEffect(() => {
    if (webrtcConnected) {
      addLog('WebRTC: Connected to dispatch control room.');
    }
  }, [webrtcConnected, addLog]);

  // Auto-dialer logic
  useEffect(() => {
    if (status === 'active' && !autoDialed) {
      addLog('Dialer: Auto-dialing emergency services (112)...');
      setAutoDialed(true);
      if (typeof window !== 'undefined') {
        window.location.href = 'tel:112';
      }
    }
  }, [status, autoDialed, setAutoDialed, addLog]);

  // Multi-frequency Bluetooth and Serial attempts
  const triggerRadioBroadcasts = useCallback(async () => {
    // 1. Web Bluetooth scan/pairing advertisement
    if (typeof navigator !== 'undefined' && 'bluetooth' in navigator) {
      addLog('Bluetooth: Scanning/advertising BLE SOS beacons...');
      try {
        await (navigator as any).bluetooth.requestDevice({
          acceptAllDevices: true,
          optionalServices: ['generic_access']
        });
        addLog('Bluetooth: Distress packet sent to nearby wearables.');
      } catch (err: any) {
        addLog(`Bluetooth: Request bypassed/denied (${err.name || 'canceled'}).`);
      }
    } else {
      addLog('Bluetooth: Hardware interface not supported.');
    }

    // 2. Web Serial API attempt for external devices
    if (typeof navigator !== 'undefined' && 'serial' in navigator) {
      addLog('Serial: Sweeping connected radio devices...');
      try {
        const ports = await (navigator as any).serial.getPorts();
        if (ports.length > 0) {
          const port = ports[0];
          await port.open({ baudRate: 9600 });
          const writer = port.writable.getWriter();
          const data = new TextEncoder().encode('SOS EMERGENCY DISTRESS - ROADSoS');
          await writer.write(data);
          writer.releaseLock();
          addLog('Serial: Distress string pushed to connected transceivers.');
        } else {
          addLog('Serial: No external radio interfaces connected.');
        }
      } catch (err: any) {
        addLog(`Serial: Sweep completed (${err.message || 'COM port busy'}).`);
      }
    } else {
      addLog('Serial: Serial broadcast not supported by browser.');
    }
  }, [addLog]);

  // Run sweeps when broadcast triggers
  useEffect(() => {
    if (status === 'active') {
      void triggerRadioBroadcasts();
    }
  }, [status, triggerRadioBroadcasts]);

  // Stream controls
  const toggleCamera = () => {
    if (stream) {
      const track = stream.getVideoTracks()[0];
      if (track) {
        track.enabled = !track.enabled;
        setCameraOn(track.enabled);
        addLog(`Camera: User turned ${track.enabled ? 'ON' : 'OFF'}`);
      }
    }
  };

  const toggleMic = () => {
    if (stream) {
      const track = stream.getAudioTracks()[0];
      if (track) {
        track.enabled = !track.enabled;
        setMicOn(track.enabled);
        addLog(`Mic: User ${track.enabled ? 'UNMUTED' : 'MUTED'}`);
      }
    }
  };

  // Poll Assigned Responder
  useEffect(() => {
    if (status !== 'active' && status !== 'acknowledged') {
      setResponderInfo(null);
      setLiveDistance(null);
      setLiveDuration(null);
      setDirectionsResponse(null);
      return;
    }

    if (responder && !responderInfo) {
      setResponderInfo({
        name: responder.name,
        lat: responder.lat,
        lng: responder.lng,
      });
    }

    const intervalId = setInterval(async () => {
      const supabase = getBrowserClient();
      let updatedLat = responderInfo?.lat;
      let updatedLng = responderInfo?.lng;
      let updatedName = responderInfo?.name;

      if (supabase && incidentId) {
        try {
          const { data } = await supabase
            .from('responders')
            .select('*')
            .eq('current_incident_id', incidentId)
            .maybeSingle();

          if (data && data.lat && data.lng) {
            updatedLat = data.lat;
            updatedLng = data.lng;
            updatedName = data.name;
          }
        } catch (e) {
          console.warn('[PanicMode] Error polling responders table:', e);
        }
      }

      // Simulation movement towards user's coordinates (closer by 8% per tick)
      if (location && updatedLat !== undefined && updatedLng !== undefined) {
        const dLat = location.lat - updatedLat;
        const dLng = location.lng - updatedLng;
        const dist = Math.sqrt(dLat * dLat + dLng * dLng);

        if (dist > 0.0001) {
          updatedLat += dLat * 0.08;
          updatedLng += dLng * 0.08;
        } else {
          updatedLat = location.lat;
          updatedLng = location.lng;
        }
      }

      if (updatedLat !== undefined && updatedLng !== undefined) {
        setResponderInfo({
          name: updatedName || responder?.name || 'Emergency Responder',
          lat: updatedLat,
          lng: updatedLng,
        });
      }
    }, 4000);

    return () => clearInterval(intervalId);
  }, [status, responder, incidentId, location, responderInfo]);

  // Directions Route Calculation
  useEffect(() => {
    if (!isLoaded || !location || !responderInfo) return;

    const directionsService = new google.maps.DirectionsService();
    directionsService.route(
      {
        origin: new google.maps.LatLng(responderInfo.lat, responderInfo.lng),
        destination: new google.maps.LatLng(location.lat, location.lng),
        travelMode: google.maps.TravelMode.DRIVING,
      },
      (result, status) => {
        if (status === google.maps.DirectionsStatus.OK && result) {
          setDirectionsResponse(result);
          const route = result.routes[0]?.legs[0];
          if (route) {
            setLiveDistance(route.distance?.text || null);
            setLiveDuration(route.duration?.text || null);
          }
        } else {
          console.warn('[Directions] API lookup failed:', status);
        }
      }
    );
  }, [isLoaded, location, responderInfo]);

  const visible = status !== 'idle' && status !== 'resolved';

  return (
    <AnimatePresence>
      {visible && (
        <motion.div
          key="panic"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className={cn(
            "fixed inset-0 z-[100] flex flex-col items-center justify-between p-6 pt-14 text-white overflow-y-auto no-scrollbar transition-colors duration-200",
            status === 'countdown'
              ? flashToggle
                ? "bg-red-650 text-white"
                : "bg-white text-red-600"
              : "bg-gray-950/98 backdrop-blur-2xl text-white"
          )}
        >
          {/* Multi-Channel Broadcast Overlay during Broadcast Phase */}
          {showBroadcast && (status === 'active' || status === 'acknowledged') && (
            <BroadcastPanel onContinue={() => setShowBroadcast(false)} />
          )}

          {/* Header */}
          <div className="w-full flex justify-between items-center shrink-0 z-10">
            <div className="flex items-center gap-2">
              <Siren className={cn("animate-pulse", status === 'countdown' && flashToggle ? "text-white" : "text-red-500")} size={20} />
              <span className={cn("text-xs font-black tracking-widest uppercase", status === 'countdown' && flashToggle ? "text-white" : "text-red-500")}>
                Emergency Protocol
              </span>
            </div>
            {status === 'countdown' && (
              <button
                onClick={cancel}
                className="flex items-center gap-1.5 bg-black/10 border border-gray-800/40 rounded-2xl px-4 py-2 text-xs font-bold hover:bg-black/20 transition-colors"
              >
                <X size={13} /> {t('sos.cancelSos', 'Cancel SOS')}
              </button>
            )}
            {(status === 'active' || status === 'acknowledged') && (
              <button
                onClick={allClear}
                className="flex items-center gap-1.5 bg-green-950/70 border border-green-700/80 rounded-2xl px-5 py-2 text-xs font-black text-green-300 hover:bg-green-900/50 transition-all shadow-[0_0_20px_rgba(34,197,94,0.1)] active:scale-98 cursor-pointer"
              >
                ✅ {t('sos.imSafe', "I'm Safe — Clear SOS")}
              </button>
            )}
          </div>

          {/* COUNTDOWN STATE CONTAINER */}
          {status === 'countdown' && (
            <div className="flex flex-col items-center justify-between flex-1 w-full max-w-md py-12 shrink-0">
              <div className="text-center space-y-2">
                <h2 className={cn("font-black text-4xl tracking-tight uppercase", flashToggle ? "text-white" : "text-red-600")}>
                  {t('sos.sosActivating', 'SOS Initiating')}
                </h2>
                <p className={cn("text-xs font-black uppercase tracking-wider", flashToggle ? "text-red-200" : "text-gray-500")}>
                  {t('sos.sendingEmergencyAlert', 'Sending emergency alert in {{seconds}}s', { seconds: countdownSeconds })}
                </p>
              </div>

              <motion.div
                className={cn(
                  "w-44 h-44 rounded-full border-[10px] flex items-center justify-center shadow-2xl relative",
                  flashToggle
                    ? "border-white bg-white/10 shadow-[0_0_60px_rgba(255,255,255,0.4)]"
                    : "border-red-650 bg-red-650/10 shadow-[0_0_65px_rgba(220,38,38,0.4)]"
                )}
                animate={{ scale: [0.95, 1.05, 0.95] }}
                transition={{ duration: 1.2, repeat: Infinity }}
              >
                <span className={cn("text-8xl font-black font-mono tracking-tight", flashToggle ? "text-white" : "text-red-600")}>
                  {countdownSeconds}
                </span>
              </motion.div>

              <div className="w-full px-4 space-y-4">
                <div className={cn("text-center text-xs p-4 rounded-2xl border bg-black/5", flashToggle ? "border-white/10 text-red-100" : "border-gray-250 text-gray-500")}>
                  <p className="font-semibold">{t('sos.telemetryLock', 'Securing high-accuracy GPS & crash telemetry packets...')}</p>
                </div>

                <button
                  onClick={cancel}
                  className={cn(
                    "w-full rounded-2xl py-4.5 text-sm font-black tracking-widest uppercase transition-all shadow-xl active:scale-98 cursor-pointer flex items-center justify-center gap-2",
                    flashToggle
                      ? "bg-white text-red-600 hover:bg-gray-100"
                      : "bg-red-600 text-white hover:bg-red-700 shadow-[0_0_20px_rgba(220,38,38,0.3)]"
                  )}
                >
                  <X size={16} /> {t('sos.cancelSosAlert', 'Cancel SOS Alert')}
                </button>
              </div>
            </div>
          )}

          {/* SOS ACTIVE EMERGENCY STATE CONTAINER */}
          {(status === 'active' || status === 'acknowledged') && !showBroadcast && (
            <div className="w-full flex-1 grid grid-cols-1 md:grid-cols-12 gap-6 max-w-6xl mt-6 mb-6">
              {/* Large Map Panel (Grid span 7/12) */}
              <div className="md:col-span-7 flex flex-col h-[350px] md:h-[550px] rounded-3xl border border-gray-850 bg-black/40 overflow-hidden relative shadow-2xl">
                {isLoaded ? (
                  <GoogleMap
                    mapContainerClassName="w-full h-full"
                    center={location || { lat: 0, lng: 0 }}
                    zoom={14}
                    options={{
                      styles: DARK_MAP_STYLE,
                      disableDefaultUI: true,
                      zoomControl: true,
                    }}
                  >
                    {location && (
                      <Marker
                        position={{ lat: location.lat, lng: location.lng }}
                        icon={{
                          path: google.maps.SymbolPath.CIRCLE,
                          scale: 10,
                          fillColor: '#ef4444',
                          fillOpacity: 1,
                          strokeColor: '#ffffff',
                          strokeWeight: 2.5,
                        }}
                      />
                    )}

                    {responderInfo && (
                      <Marker
                        position={{ lat: responderInfo.lat, lng: responderInfo.lng }}
                        icon={{
                          path: google.maps.SymbolPath.BACKWARD_CLOSED_ARROW,
                          scale: 8,
                          fillColor: '#f97316',
                          fillOpacity: 1,
                          strokeColor: '#ffffff',
                          strokeWeight: 2,
                        }}
                      />
                    )}

                    {directionsResponse && (
                      <DirectionsRenderer
                        directions={directionsResponse}
                        options={{
                          suppressMarkers: true,
                          polylineOptions: {
                            strokeColor: '#f97316',
                            strokeOpacity: 0.85,
                            strokeWeight: 5,
                          },
                        }}
                      />
                    )}
                  </GoogleMap>
                ) : (
                  <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-950/80">
                    <Loader2 className="w-8 h-8 text-red-500 animate-spin mb-2" />
                    <span className="text-xs text-gray-500 font-bold uppercase tracking-wider">Loading Emergency Map...</span>
                  </div>
                )}

                {/* Floating Location Overlay */}
                {location && (
                  <div className="absolute bottom-3 left-3 right-3 bg-gray-950/85 border border-gray-850 rounded-2xl p-3 backdrop-blur shadow-lg flex items-start gap-2.5 pointer-events-none">
                    <MapPin className="text-red-500 shrink-0 w-4 h-4 mt-0.5" />
                    <div className="overflow-hidden">
                      <span className="text-[10px] uppercase font-black tracking-widest text-red-400 block">Incident Coordinates</span>
                      <span className="text-white text-xs font-semibold block truncate mt-0.5">{location.address}</span>
                    </div>
                  </div>
                )}

                {/* Floating Map Controls / Badge */}
                <div className="absolute top-3 left-3 flex gap-2 pointer-events-none">
                  <div className="bg-red-600/90 border border-red-500/30 rounded-xl px-2.5 py-1 text-[9px] font-black tracking-widest text-white flex items-center gap-1.5 shadow-lg backdrop-blur">
                    <span className="w-1.5 h-1.5 bg-white rounded-full animate-ping" />
                    {t('sos.liveTracking', 'LIVE TRACKING')}
                  </div>
                </div>
              </div>

              {/* Info and Stream column (Grid span 5/12) */}
              <div className="md:col-span-5 flex flex-col gap-5 justify-between">
                {/* Responder ETA Tracker Card */}
                <div className="bg-gray-900/60 border border-gray-850 rounded-3xl p-5 shadow-xl relative overflow-hidden shrink-0">
                  <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
                    <Compass size={80} className="text-orange-400" />
                  </div>
                  {responderInfo ? (
                    <div className="space-y-4">
                      <div className="flex items-center justify-between">
                        <span className="text-[10px] font-black tracking-widest text-orange-400 uppercase">Assigned First Responder</span>
                        <span className="bg-orange-950 border border-orange-700/50 rounded-full px-2 py-0.5 text-[8px] font-black text-orange-300 uppercase tracking-widest">
                          En Route
                        </span>
                      </div>
                      <div className="flex items-center gap-3">
                        <div className="w-12 h-12 rounded-2xl bg-orange-950 border border-orange-700/30 flex items-center justify-center text-orange-400">
                          <Truck size={24} className="animate-bounce" />
                        </div>
                        <div>
                          <h3 className="text-white font-black text-base tracking-tight">{responderInfo.name}</h3>
                          <p className="text-gray-400 text-xs mt-0.5">Medical & Emergency Assistance unit dispatched</p>
                        </div>
                      </div>

                      {/* Directions API Info */}
                      <div className="grid grid-cols-2 gap-3 pt-3 border-t border-gray-800/40">
                        <div className="bg-black/35 border border-gray-850 rounded-xl p-3 text-center">
                          <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest block">ETA</span>
                          <span className="text-orange-400 font-black text-lg block mt-0.5">{liveDuration || `${responder?.etaMinutes || 10} mins`}</span>
                        </div>
                        <div className="bg-black/35 border border-gray-850 rounded-xl p-3 text-center">
                          <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest block">Distance</span>
                          <span className="text-white font-black text-lg block mt-0.5">{liveDistance || 'Calculating...'}</span>
                        </div>
                      </div>
                    </div>
                  ) : (
                    <div className="py-6 flex flex-col items-center justify-center text-center space-y-3">
                      <Loader2 className="w-8 h-8 text-red-500 animate-spin" />
                      <div>
                        <h3 className="text-white font-bold text-sm">Awaiting Responder Assignment</h3>
                        <p className="text-gray-500 text-xs mt-1">Dispatched alerts to nearest emergency dispatch rooms</p>
                      </div>
                    </div>
                  )}
                </div>

                {/* WebRTC Video Stream Panel */}
                <div className="w-full aspect-video bg-gray-900 border border-gray-850 rounded-3xl overflow-hidden relative shadow-2xl shrink-0">
                  {stream && cameraOn ? (
                    <video
                      ref={videoRef}
                      autoPlay
                      playsInline
                      muted
                      className="w-full h-full object-cover transform -scale-x-100"
                    />
                  ) : (
                    <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-950 p-4 text-center">
                      <CameraOff size={28} className="text-red-500 mb-2 animate-bounce" />
                      <p className="text-gray-400 text-xs font-bold">{streamError || t('sos.distressStreamActive', 'Distress stream active')}</p>
                    </div>
                  )}

                  {/* Stream Badge */}
                  <div className={cn(
                    "absolute top-3 left-3 px-2.5 py-1 rounded-full text-[9px] font-black tracking-widest text-white flex items-center gap-1.5 shadow-lg border backdrop-blur",
                    webrtcConnected ? 'bg-green-600/90 border-green-500/30' : 'bg-red-600/90 border-red-500/30'
                  )}>
                    <span className="w-1.5 h-1.5 bg-white rounded-full animate-ping" />
                    {webrtcConnected ? t('sos.dispatchConnected', 'DISPATCH CONNECTED') : t('sos.liveTelemetry', 'LIVE TELEMETRY')}
                  </div>

                  {/* Mic / Camera Quick Controls */}
                  {stream && (
                    <div className="absolute top-3 right-3 flex gap-2">
                      <button
                        onClick={toggleCamera}
                        className={cn(
                          "w-8 h-8 rounded-xl flex items-center justify-center transition-colors shadow-lg backdrop-blur cursor-pointer",
                          cameraOn ? 'bg-black/60 hover:bg-black/80 text-white border border-white/10' : 'bg-red-600 text-white border border-red-500/30'
                        )}
                      >
                        {cameraOn ? <Camera size={14} /> : <CameraOff size={14} />}
                      </button>
                      <button
                        onClick={toggleMic}
                        className={cn(
                          "w-8 h-8 rounded-xl flex items-center justify-center transition-colors shadow-lg backdrop-blur cursor-pointer",
                          micOn ? 'bg-black/60 hover:bg-black/80 text-white border border-white/10' : 'bg-red-600 text-white border border-red-500/30'
                        )}
                      >
                        {micOn ? <Mic size={14} /> : <MicOff size={14} />}
                      </button>
                    </div>
                  )}

                  {/* WebRTC Metadata Overlay */}
                  <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/90 to-transparent p-4 pt-12 flex flex-col gap-0.5 pointer-events-none">
                    <p className="text-white font-mono text-[9px] uppercase font-bold tracking-wider opacity-90 drop-shadow">
                      ID: {incidentId?.substring(0, 8) || 'UNKNOWN'}
                    </p>
                    {location && (
                      <p className="text-white font-mono text-[9px] uppercase font-bold tracking-wider opacity-90 drop-shadow truncate">
                        GPS: {location.lat.toFixed(5)}, {location.lng.toFixed(5)}
                      </p>
                    )}
                  </div>
                </div>

                {/* Sweep Console terminal */}
                <div className="bg-gray-950 border border-gray-900 rounded-2xl p-4 font-mono text-[9px] text-red-400/90 shadow-inner flex flex-col space-y-1.5 flex-1 min-h-[100px] max-h-[160px] overflow-y-auto no-scrollbar">
                  <div className="flex items-center justify-between border-b border-gray-900 pb-1.5 mb-1.5 shrink-0">
                    <span className="flex items-center gap-1.5 text-gray-500 font-bold uppercase text-[8px]"><TerminalIcon size={10} /> {t('sos.radioSweeperConsole', 'Radio Sweeper Console')}</span>
                    <span className="w-1.5 h-1.5 rounded-full bg-red-500 animate-pulse" />
                  </div>
                  <div className="space-y-1 flex-1">
                    {terminalLogs.length === 0 ? (
                      <p className="text-gray-600">{t('sos.noOutputLogs', 'No output logs.')}</p>
                    ) : (
                      terminalLogs.map((log, idx) => (
                        <p key={idx} className="truncate leading-none">{log}</p>
                      ))
                    )}
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Footer controls & channel indicators (only shown if not counting down or broadcasting) */}
          {(status === 'active' || status === 'acknowledged') && !showBroadcast && (
            <div className="w-full max-w-6xl space-y-4 shrink-0 z-10">
              {broadcastStatus && (
                <div className="space-y-2 relative overflow-hidden rounded-2xl border border-gray-850 bg-black/40 p-4">
                  {/* Sweep Animation */}
                  <motion.div
                    className="absolute inset-y-0 w-12 bg-gradient-to-r from-transparent via-red-500/10 to-transparent pointer-events-none skew-x-[-20deg]"
                    animate={{ left: ['-100%', '200%'] }}
                    transition={{ duration: 2.5, ease: "linear", repeat: Infinity }}
                  />
                  <p className="text-gray-500 text-[10px] font-black uppercase tracking-wider flex items-center gap-1 mb-2 relative z-10">
                    <Radio size={10} /> {t('sos.transmissionStatus', 'Transmission Channels Active')}
                  </p>
                  <div className="grid grid-cols-4 md:grid-cols-8 gap-2 relative z-10">
                    {Object.entries(broadcastStatus).map(([ch, stat]) => (
                      <div
                        key={ch}
                        className={cn(
                          "rounded-xl px-1 py-2 text-center border text-[9px] font-black uppercase tracking-tight shadow-inner transition-colors",
                          stat === 'sent' || stat === 'broadcast' || stat === 'link_generated' || stat === 'published' || stat === 'connected'
                            ? 'bg-green-950/80 border-green-700 text-green-400'
                            : stat === 'pending'
                            ? 'bg-yellow-950/80 border-yellow-700 text-yellow-400 animate-pulse'
                            : stat === 'stub' || stat === 'attempted'
                            ? 'bg-gray-900/80 border-gray-800 text-gray-400'
                            : 'bg-red-950/80 border-red-900 text-red-400'
                        )}
                      >
                        {ch}
                        <div className="text-[7px] mt-0.5 opacity-70 lowercase font-bold">{stat}</div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {/* LiveStreamPanel floating overlay */}
          {(status === 'active' || status === 'acknowledged') && (
            <LiveStreamPanel
              stream={activeStream}
              peers={activePeers}
              onStop={() => {
                if (stopFnRef.current) {
                  stopFnRef.current();
                  stopFnRef.current = null;
                }
                setActiveStream(null);
                setActivePeers({});
                setStream(null);
                addLog('WebRTC: Emergency stream manually stopped by user.');
              }}
            />
          )}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

'use client';

import { useEffect, useRef, useState, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useSOSStore } from '@/lib/store/sosStore';
import { useRouter } from 'next/navigation';
import { Mic, MicOff, Volume2, HelpCircle, X, ShieldAlert, Sparkles, HelpCircle as HelpIcon } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { cn } from '@/lib/utils';

const LANGUAGE_LOCALE_MAP: Record<string, string> = {
  en: 'en-US',
  hi: 'hi-IN',
  gu: 'gu-IN',
  es: 'es-ES',
  fr: 'fr-FR',
  ar: 'ar-SA',
  pt: 'pt-BR',
  zh: 'zh-CN',
  bn: 'bn-IN',
  ru: 'ru-RU',
};

const LANG_NAME_TO_CODE: Record<string, string> = {
  hindi: 'hi',
  gujarati: 'gu',
  spanish: 'es',
  french: 'fr',
  arabic: 'ar',
  portuguese: 'pt',
  chinese: 'zh',
  bengali: 'bn',
  russian: 'ru',
  english: 'en',
};

export function VoiceCommands() {
  const { i18n, t } = useTranslation();
  const [listening, setListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [feedback, setFeedback] = useState('');
  const [showHelp, setShowHelp] = useState(false);
  const [isWhisperRecording, setIsWhisperRecording] = useState(false);
  const [whisperLoading, setWhisperLoading] = useState(false);

  const recognitionRef = useRef<any>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const router = useRouter();
  const { arm } = useSOSStore();

  const speak = useCallback((text: string) => {
    setFeedback(text);
    if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const utter = new SpeechSynthesisUtterance(text);
      utter.rate = 1.1;
      utter.lang = LANGUAGE_LOCALE_MAP[i18n.language] || 'en-US';
      window.speechSynthesis.speak(utter);
    }
    setTimeout(() => setFeedback(''), 4000);
  }, [i18n.language]);

  // Execute Voice Command Actions
  const executeCommand = useCallback((lower: string) => {
    // 1. SOS commands
    if (
      lower.includes('send sos') ||
      lower.includes('activate sos') ||
      lower.includes('activate panic mode') ||
      lower.includes('panic mode')
    ) {
      arm('voice');
      speak(t('SOS activated — broadcasting emergency beacon'));
      return true;
    }

    // 2. Navigation commands
    if (lower.includes('open map') || lower.includes('show map')) {
      router.push('/map');
      speak(t('Opening emergency map'));
      return true;
    }
    if (lower.includes('find nearest hospital') || lower.includes('nearest hospital')) {
      router.push('/map?find=hospital');
      speak(t('Locating nearest hospital on the map'));
      return true;
    }
    if (lower.includes('open chat') || lower.includes('open chatbot') || lower.includes('open assistant')) {
      router.push('/chat');
      speak(t('Opening AI chat assistant'));
      return true;
    }
    if (lower.includes('open first aid') || lower.includes('first aid')) {
      router.push('/first-aid');
      speak(t('Opening first aid guidelines'));
      return true;
    }
    if (lower.includes('open directory') || lower.includes('emergency contacts')) {
      router.push('/directory');
      speak(t('Opening emergency phone directory'));
      return true;
    }
    if (lower.includes('open settings') || lower.includes('settings')) {
      router.push('/settings');
      speak(t('Opening profile settings'));
      return true;
    }
    if (lower.includes('go home') || lower.includes('open dashboard') || lower.includes('go back')) {
      router.push('/');
      speak(t('Opening main driver dashboard'));
      return true;
    }

    // 3. Dialing commands
    if (lower.includes('call 108') || lower.includes('call ambulance')) {
      window.location.href = 'tel:108';
      speak(t('Calling emergency ambulance 108'));
      return true;
    }
    if (lower.includes('call police') || lower.includes('call 100')) {
      window.location.href = 'tel:100';
      speak(t('Calling police department'));
      return true;
    }
    if (lower.includes('call fire') || lower.includes('call 101')) {
      window.location.href = 'tel:101';
      speak(t('Calling fire brigade emergency'));
      return true;
    }
    if (lower.includes('call 112') || lower.includes('call help')) {
      window.location.href = 'tel:112';
      speak(t('Calling national emergency line 112'));
      return true;
    }

    // 4. Language selection commands
    for (const [langName, langCode] of Object.entries(LANG_NAME_TO_CODE)) {
      if (lower.includes(`switch language to ${langName}`) || lower.includes(`change language to ${langName}`)) {
        void i18n.changeLanguage(langCode);
        speak(`Language switched to ${langName}`);
        return true;
      }
    }

    // 5. Help overlay trigger
    if (lower.includes('show commands') || lower.includes('help commands') || lower.includes('voice help')) {
      setShowHelp(true);
      speak(t('Displaying available voice commands overlay'));
      return true;
    }
    if (lower.includes('close commands') || lower.includes('hide commands') || lower.includes('dismiss commands')) {
      setShowHelp(false);
      speak(t('Dismissed help commands'));
      return true;
    }

    return false;
  }, [router, arm, speak, i18n, t]);

  // Main command processing logic (Local Speech + Whisper results)
  const processTranscript = useCallback((text: string) => {
    const lower = text.toLowerCase().trim();

    // Check if command executes
    const handled = executeCommand(lower);
    if (handled) return;

    // Wake word response if no command matches
    if (lower.includes('hey emergency') || lower.includes('sos help')) {
      speak(t('Listening. Say "Show commands" or give a navigation instruction.'));
    }
  }, [executeCommand, speak, t]);

  // Speech Recognition Setup (Web Speech API)
  useEffect(() => {
    const w = window as any;
    if (!w.SpeechRecognition && !w.webkitSpeechRecognition) return;

    const SpeechRecognitionClass = w.SpeechRecognition || w.webkitSpeechRecognition;
    const recognition = new SpeechRecognitionClass();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = LANGUAGE_LOCALE_MAP[i18n.language] || 'en-US';

    recognition.onresult = (e: any) => {
      const latest = e.results[e.results.length - 1];
      const text = latest[0].transcript;
      setTranscript(text);
      if (latest.isFinal) {
        processTranscript(text);
        setTranscript('');
      }
    };

    recognition.onerror = (err: any) => {
      console.error('[Voice] Recognition error:', err);
      // Don't auto-stop on quiet breaks
      if (err.error !== 'no-speech') {
        setListening(false);
      }
    };

    recognition.onend = () => {
      if (listening && !isWhisperRecording) {
        try {
          recognition.start();
        } catch {}
      }
    };

    recognitionRef.current = recognition;

    if (listening && !isWhisperRecording) {
      try {
        recognition.start();
      } catch {}
    }

    return () => {
      try {
        recognition.stop();
      } catch {}
    };
  }, [listening, i18n.language, isWhisperRecording, processTranscript]);

  // Background SpeechRecognition Listener for passive "send sos" detection
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const w = window as any;
    if (!w.SpeechRecognition && !w.webkitSpeechRecognition) return;

    const SpeechRecognitionClass = w.SpeechRecognition || w.webkitSpeechRecognition;
    const bgRecognition = new SpeechRecognitionClass();
    bgRecognition.continuous = true;
    bgRecognition.interimResults = true;
    bgRecognition.lang = 'en-US';

    let active = true;

    bgRecognition.onresult = (e: any) => {
      if (!active) return;
      for (let i = e.resultIndex; i < e.results.length; i++) {
        const result = e.results[i];
        const text = result[0].transcript.toLowerCase();
        if (
          text.includes('send sos') ||
          text.includes('activate sos') ||
          text.includes('activate panic mode') ||
          text.includes('panic mode')
        ) {
          console.warn('[Voice] Background voice command SOS detected:', text);
          arm('voice');
          speak(t('SOS activated by voice command'));
          break;
        }
      }
    };

    bgRecognition.onerror = (err: any) => {
      // Ignore normal silent speech timeouts
    };

    bgRecognition.onend = () => {
      if (active && !listening && !isWhisperRecording) {
        try {
          bgRecognition.start();
        } catch {}
      }
    };

    if (!listening && !isWhisperRecording) {
      try {
        bgRecognition.start();
      } catch (e) {
        console.debug('[Voice] Could not start background listener:', e);
      }
    }

    return () => {
      active = false;
      try {
        bgRecognition.stop();
      } catch {}
    };
  }, [listening, isWhisperRecording, arm, speak, t]);

  const toggleListening = () => {
    if (listening) {
      if (recognitionRef.current) {
        try {
          recognitionRef.current.stop();
        } catch {}
      }
      setListening(false);
      setTranscript('');
    } else {
      setListening(true);
      speak(t('Voice navigator active. Speak wake word "Hey Emergency" or navigation commands.'));
    }
  };

  // ── OpenAI Whisper Recording Fallback ──────────────────────────────
  const startWhisperRecording = async () => {
    try {
      // Pause local recognition during recording to avoid conflicts
      if (recognitionRef.current) {
        try {
          recognitionRef.current.stop();
        } catch {}
      }

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };

      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        await uploadAudioToWhisper(audioBlob);

        // Stop audio tracks
        stream.getTracks().forEach((track) => track.stop());

        // Resume local recognition if active
        if (listening) {
          try {
            recognitionRef.current.start();
          } catch {}
        }
      };

      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.start();
      setIsWhisperRecording(true);
      speak(t('Whisper recording... speak your command.'));
    } catch (err) {
      console.error('Failed to start Whisper recording:', err);
      speak(t('Microphone access denied.'));
    }
  };

  const stopWhisperRecording = () => {
    if (mediaRecorderRef.current && isWhisperRecording) {
      mediaRecorderRef.current.stop();
      setIsWhisperRecording(false);
    }
  };

  const uploadAudioToWhisper = async (blob: Blob) => {
    setWhisperLoading(true);
    try {
      const formData = new FormData();
      formData.append('file', blob, 'audio.wav');

      const res = await fetch('/api/voice/whisper', {
        method: 'POST',
        body: formData,
      });

      if (!res.ok) throw new Error('Whisper server failed');
      const data = await res.json();
      const text = data.text;

      if (text) {
        setTranscript(text);
        speak(`Whisper parsed: "${text}"`);
        setTimeout(() => {
          processTranscript(text);
          setTranscript('');
        }, 1500);
      } else {
        speak(t('Could not transcribe audio.'));
      }
    } catch (err) {
      console.error('Whisper transcription error:', err);
      speak(t('Whisper link failed. Using local recognition.'));
    } finally {
      setWhisperLoading(false);
    }
  };

  const handleHelpClick = () => {
    setShowHelp(!showHelp);
  };

  return (
    <>
      {/* Voice Controls Bar */}
      <div className="fixed bottom-24 left-4 z-40 flex items-center gap-2">
        {/* Local Web Speech Trigger */}
        <motion.button
          onClick={toggleListening}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={cn(
            'w-12 h-12 rounded-full shadow-2xl flex items-center justify-center border text-white transition-all',
            listening ? 'bg-red-600 border-red-500' : 'bg-gray-900 border-gray-800 hover:border-gray-700'
          )}
          aria-label={listening ? 'Disable Voice Navigation' : 'Enable Voice Navigation'}
        >
          {listening ? (
            <motion.div animate={{ scale: [1, 1.15, 1] }} transition={{ repeat: Infinity, duration: 0.8 }}>
              <Mic size={18} />
            </motion.div>
          ) : (
            <MicOff size={18} className="text-gray-400" />
          )}
        </motion.button>

        {/* Whisper Press-to-Speak Trigger */}
        <motion.button
          onMouseDown={startWhisperRecording}
          onMouseUp={stopWhisperRecording}
          onTouchStart={startWhisperRecording}
          onTouchEnd={stopWhisperRecording}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={cn(
            'w-12 h-12 rounded-full shadow-2xl flex items-center justify-center border text-white transition-all',
            isWhisperRecording
              ? 'bg-purple-600 border-purple-500 animate-pulse'
              : whisperLoading
              ? 'bg-purple-900 border-purple-800'
              : 'bg-gray-900 border-gray-800 hover:border-purple-900'
          )}
          title="Hold for Whisper Transcription (OpenAI)"
          aria-label="Hold to speak with Whisper"
        >
          {whisperLoading ? (
            <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
          ) : (
            <Sparkles size={18} className={cn(isWhisperRecording ? 'text-white' : 'text-purple-400')} />
          )}
        </motion.button>

        {/* Help overlay trigger */}
        <motion.button
          onClick={handleHelpClick}
          whileHover={{ scale: 1.05 }}
          className="w-8 h-8 rounded-full bg-gray-900 border border-gray-800 flex items-center justify-center text-gray-400 hover:text-white"
          title="Show voice commands list"
        >
          <HelpIcon size={14} />
        </motion.button>
      </div>

      {/* Pulse / Waveform Overlay when active */}
      <AnimatePresence>
        {(listening || isWhisperRecording) && (
          <motion.div
            initial={{ opacity: 0, y: 15 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 15 }}
            className="fixed bottom-38 left-4 z-40 bg-gray-950/90 border border-gray-800 rounded-3xl p-4 w-[280px] shadow-2xl backdrop-blur-md"
          >
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] uppercase font-black tracking-widest text-red-500">
                {isWhisperRecording ? 'Whisper Rec' : 'Voice Command'}
              </span>
              {/* Waveform indicator */}
              <div className="flex items-end gap-0.5 h-3">
                {Array.from({ length: 12 }).map((_, i) => (
                  <motion.div
                    key={i}
                    className={cn('w-0.5 rounded-full', isWhisperRecording ? 'bg-purple-500' : 'bg-red-500')}
                    animate={{ height: [3, Math.max(3, (isWhisperRecording ? 14 : 9) - (i % 3) * 3), 3] }}
                    transition={{
                      duration: 0.5,
                      repeat: Infinity,
                      delay: i * 0.04,
                    }}
                  />
                ))}
              </div>
            </div>

            <p className="text-white text-xs font-medium leading-relaxed italic">
              {transcript ? `"${transcript}"` : t('Listening for "Hey Emergency"...')}
            </p>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Visual Feedback Banner */}
      <AnimatePresence>
        {feedback && (
          <motion.div
            initial={{ opacity: 0, y: -20, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -20, x: '-50%' }}
            className="fixed top-20 left-1/2 -translate-x-1/2 z-50 bg-gray-900/90 border border-red-500/30 text-white text-xs font-black uppercase tracking-wider px-4 py-2.5 rounded-full shadow-2xl backdrop-blur flex items-center gap-2"
          >
            <Volume2 size={13} className="text-red-500 animate-bounce" />
            <span>{feedback}</span>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Voice Help Overlay Modal */}
      <AnimatePresence>
        {showHelp && (
          <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
            <motion.div
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              className="bg-gray-950 border border-gray-800 rounded-3xl w-full max-w-md overflow-hidden shadow-2xl"
            >
              {/* Header */}
              <div className="flex items-center justify-between p-5 border-b border-gray-900">
                <div className="flex items-center gap-2">
                  <ShieldAlert className="text-red-500" size={18} />
                  <h3 className="text-white font-black text-sm tracking-tight">Voice Command Assistant</h3>
                </div>
                <button
                  onClick={() => setShowHelp(false)}
                  className="p-1.5 rounded-xl hover:bg-gray-900 transition-colors"
                >
                  <X size={16} className="text-gray-400" />
                </button>
              </div>

              {/* Commands List */}
              <div className="p-5 max-h-[350px] overflow-y-auto space-y-4">
                <p className="text-gray-400 text-xs leading-relaxed">
                  Toggle voice navigation using the mic button, then say the wake word <strong className="text-red-400">"Hey Emergency"</strong> followed by any of the commands listed below.
                </p>

                <div className="space-y-2">
                  <h4 className="text-[10px] font-black uppercase tracking-widest text-gray-500">SOS Operations</h4>
                  <div className="grid grid-cols-1 gap-1.5">
                    <div className="bg-gray-900 px-3 py-2 rounded-xl border border-gray-850 flex items-center justify-between text-xs">
                      <span className="text-gray-400">Arm Panic Mode</span>
                      <strong className="text-white font-mono">"Send SOS" / "Activate SOS"</strong>
                    </div>
                  </div>
                </div>

                <div className="space-y-2">
                  <h4 className="text-[10px] font-black uppercase tracking-widest text-gray-500">Navigation & Views</h4>
                  <div className="grid grid-cols-1 gap-1.5">
                    <div className="bg-gray-900 px-3 py-2 rounded-xl border border-gray-850 flex items-center justify-between text-xs">
                      <span className="text-gray-400">Open Map</span>
                      <strong className="text-white font-mono">"Open Map" / "Show Map"</strong>
                    </div>
                    <div className="bg-gray-900 px-3 py-2 rounded-xl border border-gray-850 flex items-center justify-between text-xs">
                      <span className="text-gray-400">Search Hospitals</span>
                      <strong className="text-white font-mono">"Find nearest hospital"</strong>
                    </div>
                    <div className="bg-gray-900 px-3 py-2 rounded-xl border border-gray-850 flex items-center justify-between text-xs">
                      <span className="text-gray-400">Launch AI Assistant</span>
                      <strong className="text-white font-mono">"Open Chat"</strong>
                    </div>
                    <div className="bg-gray-900 px-3 py-2 rounded-xl border border-gray-850 flex items-center justify-between text-xs">
                      <span className="text-gray-400">First Aid Guidelines</span>
                      <strong className="text-white font-mono">"First Aid"</strong>
                    </div>
                    <div className="bg-gray-900 px-3 py-2 rounded-xl border border-gray-850 flex items-center justify-between text-xs">
                      <span className="text-gray-400">Home Dashboard</span>
                      <strong className="text-white font-mono">"Go Home"</strong>
                    </div>
                  </div>
                </div>

                <div className="space-y-2">
                  <h4 className="text-[10px] font-black uppercase tracking-widest text-gray-500">Hotlines (Auto-Call)</h4>
                  <div className="grid grid-cols-1 gap-1.5">
                    <div className="bg-gray-900 px-3 py-2 rounded-xl border border-gray-850 flex items-center justify-between text-xs">
                      <span className="text-gray-400">Ambulance</span>
                      <strong className="text-white font-mono">"Call 108" / "Call Ambulance"</strong>
                    </div>
                    <div className="bg-gray-900 px-3 py-2 rounded-xl border border-gray-850 flex items-center justify-between text-xs">
                      <span className="text-gray-400">Police Dispatcher</span>
                      <strong className="text-white font-mono">"Call Police" / "Call 100"</strong>
                    </div>
                  </div>
                </div>

                <div className="space-y-2">
                  <h4 className="text-[10px] font-black uppercase tracking-widest text-gray-500">Multilingual Settings</h4>
                  <div className="grid grid-cols-1 gap-1.5">
                    <div className="bg-gray-900 px-3 py-2 rounded-xl border border-gray-850 flex items-center justify-between text-xs">
                      <span className="text-gray-400">Switch Locale</span>
                      <strong className="text-white font-mono">"Switch language to Hindi"</strong>
                    </div>
                  </div>
                </div>
              </div>

              {/* Footer */}
              <div className="bg-gray-900/60 p-4 border-t border-gray-900 text-center text-[10px] text-gray-500">
                To close, click the X or say <strong className="text-gray-400">"Close commands"</strong>.
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </>
  );
}

'use client';

import { useEffect, useRef, useCallback } from 'react';
import { useSOSStore } from '@/lib/store/sosStore';
import { useCrashStore, type CrashSensitivity } from '@/lib/store/crashStore';

let alarmStopFn: (() => void) | null = null;

const playAlertTone = (): (() => void) => {
  if (typeof window === 'undefined') return () => {};

  try {
    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    const audioCtx = new AudioContextClass();
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();

    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(880, audioCtx.currentTime);

    // Siren warble frequency modulation
    let isHigh = true;
    const interval = setInterval(() => {
      if (audioCtx.state === 'closed') {
        clearInterval(interval);
        return;
      }
      const targetFreq = isHigh ? 440 : 880;
      osc.frequency.linearRampToValueAtTime(targetFreq, audioCtx.currentTime + 0.4);
      isHigh = !isHigh;
    }, 500);

    gain.gain.setValueAtTime(0.8, audioCtx.currentTime);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start();

    return () => {
      clearInterval(interval);
      try {
        osc.stop();
        osc.disconnect();
        gain.disconnect();
        audioCtx.close();
      } catch (err) {
        console.warn('Audio Context release error:', err);
      }
    };
  } catch (err) {
    console.warn('Web Audio Context initialization blocked or unsupported:', err);
    return () => {};
  }
};

export function useCrashDetection() {
  const armSOS = useSOSStore((s) => s.arm);

  const {
    isCrashMonitoring,
    sensitivity,
    crashTriggered,
    countdownSeconds,
    setCrashMonitoring,
    setSensitivity,
    setCrashTriggered,
    setCountdownSeconds,
    setTriggerReason,
    resetCrash,
  } = useCrashStore();

  const motionStart40Ref = useRef<number>(0);
  const motionStart25Ref = useRef<number>(0);
  const lastNormalTiltRef = useRef<number>(0);
  const countdownIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Set sensitivity thresholds
  const getThresholds = useCallback(() => {
    switch (sensitivity) {
      case 'high':
        return { crash: 30, impact: 18, tilt: 45 };
      case 'low':
        return { crash: 50, impact: 35, tilt: 75 };
      case 'normal':
      default:
        return { crash: 40, impact: 25, tilt: 60 };
    }
  }, [sensitivity]);

  const triggerCrashFlow = useCallback((reason: 'crash likely' | 'impact detected' | 'rollover possible') => {
    if (useCrashStore.getState().crashTriggered) return;

    setCrashTriggered(true);
    setTriggerReason(reason);
    setCountdownSeconds(15);

    // Play loud alert tone
    if (alarmStopFn) alarmStopFn();
    alarmStopFn = playAlertTone();

    // Start 15s countdown
    if (countdownIntervalRef.current) clearInterval(countdownIntervalRef.current);
    countdownIntervalRef.current = setInterval(() => {
      const currentVal = useCrashStore.getState().countdownSeconds;
      if (currentVal <= 1) {
        // Trigger SOS !
        if (countdownIntervalRef.current) clearInterval(countdownIntervalRef.current);
        if (alarmStopFn) {
          alarmStopFn();
          alarmStopFn = null;
        }

        // Execute SOS trigger
        armSOS('crash');
        useCrashStore.getState().resetCrash();
      } else {
        setCountdownSeconds(currentVal - 1);
      }
    }, 1000);
  }, [setCrashTriggered, setTriggerReason, setCountdownSeconds, armSOS]);

  const handleCancel = useCallback(() => {
    if (countdownIntervalRef.current) {
      clearInterval(countdownIntervalRef.current);
      countdownIntervalRef.current = null;
    }
    if (alarmStopFn) {
      alarmStopFn();
      alarmStopFn = null;
    }
    resetCrash();
  }, [resetCrash]);

  // Motion analysis
  const handleDeviceMotion = useCallback((e: DeviceMotionEvent) => {
    if (!isCrashMonitoring || useCrashStore.getState().crashTriggered) return;

    const acc = e.acceleration || e.accelerationIncludingGravity;
    if (!acc) return;

    const x = acc.x ?? 0;
    const y = acc.y ?? 0;
    const z = acc.z ?? 0;
    const magnitude = Math.sqrt(x * x + y * y + z * z);

    const thresholds = getThresholds();

    // 1. Crash likely (>40 m/s^2 for 200ms)
    if (magnitude > thresholds.crash) {
      const now = Date.now();
      if (motionStart40Ref.current === 0) {
        motionStart40Ref.current = now;
      }
      if (now - motionStart40Ref.current >= 200) {
        motionStart40Ref.current = 0; // reset
        triggerCrashFlow('crash likely');
      }
    } else {
      motionStart40Ref.current = 0;
    }

    // 2. Impact detected (>25 m/s^2 for 500ms)
    if (magnitude > thresholds.impact) {
      const now = Date.now();
      if (motionStart25Ref.current === 0) {
        motionStart25Ref.current = now;
      }
      if (now - motionStart25Ref.current >= 500) {
        motionStart25Ref.current = 0; // reset
        triggerCrashFlow('impact detected');
      }
    } else {
      motionStart25Ref.current = 0;
    }
  }, [isCrashMonitoring, getThresholds, triggerCrashFlow]);

  // Orientation analysis
  const handleDeviceOrientation = useCallback((e: DeviceOrientationEvent) => {
    if (!isCrashMonitoring || useCrashStore.getState().crashTriggered) return;

    const beta = e.beta;
    const gamma = e.gamma;
    if (beta === null || gamma === null) return;

    const absBeta = Math.abs(beta);
    const absGamma = Math.abs(gamma);

    const thresholds = getThresholds();
    const now = Date.now();

    // Check if flat/normal tilt
    if (absBeta < 15 && absGamma < 15) {
      lastNormalTiltRef.current = now;
    }

    // Rollover: tilt > threshold in < 1s
    if (absBeta > thresholds.tilt || absGamma > thresholds.tilt) {
      if (lastNormalTiltRef.current !== 0 && now - lastNormalTiltRef.current < 1000) {
        lastNormalTiltRef.current = 0;
        triggerCrashFlow('rollover possible');
      }
    }
  }, [isCrashMonitoring, getThresholds, triggerCrashFlow]);

  const startMonitoring = useCallback(async () => {
    setCrashMonitoring(true);

    // Request permission on iOS 13+
    if (
      typeof window !== 'undefined' &&
      typeof (DeviceMotionEvent as any).requestPermission === 'function'
    ) {
      try {
        const state = await (DeviceMotionEvent as any).requestPermission();
        if (state === 'granted') {
          window.addEventListener('devicemotion', handleDeviceMotion);
          window.addEventListener('deviceorientation', handleDeviceOrientation);
        }
      } catch (err) {
        console.warn('iOS motion sensor permission request rejected:', err);
      }
    } else if (typeof window !== 'undefined') {
      window.addEventListener('devicemotion', handleDeviceMotion);
      window.addEventListener('deviceorientation', handleDeviceOrientation);
    }
  }, [setCrashMonitoring, handleDeviceMotion, handleDeviceOrientation]);

  const stopMonitoring = useCallback(() => {
    setCrashMonitoring(false);
    if (typeof window !== 'undefined') {
      window.removeEventListener('devicemotion', handleDeviceMotion);
      window.removeEventListener('deviceorientation', handleDeviceOrientation);
    }
    handleCancel();
  }, [setCrashMonitoring, handleDeviceMotion, handleDeviceOrientation, handleCancel]);

  useEffect(() => {
    if (isCrashMonitoring) {
      void startMonitoring();
    }
    return () => {
      if (typeof window !== 'undefined') {
        window.removeEventListener('devicemotion', handleDeviceMotion);
        window.removeEventListener('deviceorientation', handleDeviceOrientation);
      }
    };
  }, [isCrashMonitoring, startMonitoring, handleDeviceMotion, handleDeviceOrientation]);

  return {
    isCrashMonitoring,
    startMonitoring,
    stopMonitoring,
    sensitivity,
    setSensitivity,
    handleCancel,
  };
}

