const LANG_NAMES: Record<string, string> = {
  hindi: 'hi',
  gujarati: 'gu',
  spanish: 'es',
  french: 'fr',
  arabic: 'ar',
  portuguese: 'pt',
  chinese: 'zh',
  bengali: 'bn',
  russian: 'ru',
  english: 'en',
};

export function useVoiceCommands() {
  const router = useRouter();
  const { i18n } = useTranslation();
  const { setTheme } = useTheme();

  // SOS and Chat store triggers
  const armSOS = useSOSStore((s) => s.arm);
  const setChatOpen = useChatStore((s) => s.toggle);
  const isChatOpen = useChatStore((s) => s.isOpen);

  // Voice store getters/setters
  const {
    isListening,
    transcript,
    lastCommand,
    isCommandMode,
    setListening,
    setTranscript,
    setLastCommand,
    setOverlayOpen,
    setCommandMode,
    setCommandText,
    setShowGreenFlash,
  } = useVoiceStore();

  const recognitionRef = useRef<any>(null);
  const commandModeTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const greenFlashTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const speak = useCallback((text: string) => {
    if (typeof window === 'undefined' || !('speechSynthesis' in window)) return;
    window.speechSynthesis.cancel();
    const utter = new SpeechSynthesisUtterance(text);
    utter.rate = 1.1;
    utter.lang = LANGUAGE_LOCALE_MAP[i18n.language] || 'en-US';
    window.speechSynthesis.speak(utter);
  }, [i18n.language]);

  const speakConfirmation = useCallback((type: string) => {
    const lang = i18n.language || 'en';
    const dict = CONFIRMATIONS[lang] || CONFIRMATIONS['en'];
    const phrase = dict[type] || dict['default'];
    speak(phrase);
  }, [i18n.language, speak]);

  const executeCommand = useCallback((cmd: string): boolean => {
    const cleanCmd = cmd.toLowerCase().trim();

    // Brief green flash and text display helper
    const triggerVisualFeedback = (text: string) => {
      setLastCommand(text);
      setCommandText(text);
      setShowGreenFlash(true);
      if (greenFlashTimeoutRef.current) clearTimeout(greenFlashTimeoutRef.current);
      greenFlashTimeoutRef.current = setTimeout(() => {
        setShowGreenFlash(false);
      }, 2000);
    };

    // 1. SOS activation
    if (
      cleanCmd.includes('send sos') ||
      cleanCmd.includes('activate sos') ||
      cleanCmd.includes('emergency')
    ) {
      triggerVisualFeedback('SOS Activated');
      armSOS('voice');
      speakConfirmation('sos');
      return true;
    }

    // 2. Navigation
    if (cleanCmd.includes('open map') || cleanCmd.includes('show map')) {
      triggerVisualFeedback('Open Map');
      router.push('/map');
      speakConfirmation('map');
      return true;
    }

    if (cleanCmd.includes('find hospital') || cleanCmd.includes('nearest hospital')) {
      triggerVisualFeedback('Find Hospital');
      router.push('/map?filter=hospital');
      speakConfirmation('hospital');
      return true;
    }

    // 3. Hotlines
    if (
      cleanCmd.includes('call ambulance') ||
      cleanCmd.includes('call 108') ||
      cleanCmd.includes('call 112')
    ) {
      triggerVisualFeedback('Calling Ambulance');
      speakConfirmation('default');
      window.location.href = 'tel:108';
      return true;
    }

    // 4. Open Chat Widget
    if (cleanCmd.includes('open chat') || cleanCmd.includes('talk to ai')) {
      triggerVisualFeedback('Open AI Chat');
      if (!isChatOpen) {
        setChatOpen();
      }
      speakConfirmation('chat');
      return true;
    }

    // 5. Dark / Light Mode Toggle
    if (cleanCmd.includes('dark mode')) {
      triggerVisualFeedback('Dark Mode');
      setTheme('dark');
      speakConfirmation('dark');
      return true;
    }

    if (cleanCmd.includes('light mode')) {
      triggerVisualFeedback('Light Mode');
      setTheme('light');
      speakConfirmation('light');
      return true;
    }

    // 6. Language Swapping
    for (const [langName, code] of Object.entries(LANG_NAMES)) {
      if (
        cleanCmd.includes(`change language to ${langName}`) ||
        cleanCmd.includes(`switch to ${langName}`) ||
        cleanCmd.includes(`switch language to ${langName}`)
      ) {
        triggerVisualFeedback(`Switching to ${langName}`);
        void i18n.changeLanguage(code);
        speakConfirmation('lang');
        return true;
      }
    }

    // 7. Show Commands Help
    if (cleanCmd.includes('show commands') || cleanCmd.includes('help')) {
      triggerVisualFeedback('Opening Help');
      setOverlayOpen(true);
      speakConfirmation('help');
      return true;
    }

    // 8. Cancel / Deactivate
    if (cleanCmd.includes('cancel') || cleanCmd.includes('stop listening')) {
      triggerVisualFeedback('Deactivating Voice Commands');
      setListening(false);
      speakConfirmation('cancel');
      if (recognitionRef.current) {
        try {
          recognitionRef.current.stop();
        } catch {}
      }
      return true;
    }

    return false;
  }, [router, i18n, setTheme, armSOS, isChatOpen, setChatOpen, setListening, setLastCommand, setCommandText, setShowGreenFlash, setOverlayOpen, speakConfirmation]);

  // Command mode timer handler
  const handleWakeWord = useCallback(() => {
    setCommandMode(true);
    speak(i18n.language === 'hi' ? 'जी, मैं सुन रहा हूँ। आदेश दें।' : 'Command mode active. Speak now.');

    if (commandModeTimeoutRef.current) clearTimeout(commandModeTimeoutRef.current);
    commandModeTimeoutRef.current = setTimeout(() => {
      setCommandMode(false);
    }, 5000);
  }, [i18n.language, speak, setCommandMode]);

  const processText = useCallback((text: string) => {
    const cleanText = text.toLowerCase();

    // Always detect wake words
    if (cleanText.includes('hey emergency') || cleanText.includes('sos help')) {
      handleWakeWord();
      return;
    }

    // If in command mode OR if standard command matches directly
    if (isCommandMode) {
      const executed = executeCommand(cleanText);
      if (executed) {
        setCommandMode(false);
        if (commandModeTimeoutRef.current) clearTimeout(commandModeTimeoutRef.current);
      }
    } else {
      // Allow direct command execution without wake word as a failsafe/convenience
      executeCommand(cleanText);
    }
  }, [isCommandMode, handleWakeWord, executeCommand, setCommandMode]);

  const startListening = useCallback(() => {
    setListening(true);
    speak(i18n.language === 'hi' ? 'आवाज गाइड सक्रिय' : 'Voice commands enabled');
    if (recognitionRef.current) {
      try {
        recognitionRef.current.start();
      } catch {}
    }
  }, [setListening, speak, i18n.language]);

  const stopListening = useCallback(() => {
    setListening(false);
    if (recognitionRef.current) {
      try {
        recognitionRef.current.stop();
      } catch {}
    }
  }, [setListening]);

  // Setup browser Speech Recognition
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const w = window as any;
    const SpeechRecognitionClass = w.SpeechRecognition || w.webkitSpeechRecognition;
    if (!SpeechRecognitionClass) {
      console.warn('Speech recognition not supported in this browser.');
      return;
    }

    const rec = new SpeechRecognitionClass();
    rec.continuous = true;
    rec.interimResults = true;
    rec.lang = LANGUAGE_LOCALE_MAP[i18n.language] || 'en-US';

    rec.onresult = (event: any) => {
      const latest = event.results[event.results.length - 1];
      const text = latest[0].transcript;
      setTranscript(text);

      if (latest.isFinal) {
        processText(text);
        // Clear transcript after processing
        setTimeout(() => setTranscript(''), 1000);
      }
    };

    rec.onerror = (event: any) => {
      if (event.error !== 'no-speech') {
        console.warn('Speech recognition error:', event.error);
      }
    };

    rec.onend = () => {
      // Restart if still set to listening
      if (useVoiceStore.getState().isListening) {
        try {
          rec.start();
        } catch {}
      }
    };

    recognitionRef.current = rec;

    if (isListening) {
      try {
        rec.start();
      } catch {}
    }

    return () => {
      try {
        rec.stop();
      } catch {}
      if (commandModeTimeoutRef.current) clearTimeout(commandModeTimeoutRef.current);
      if (greenFlashTimeoutRef.current) clearTimeout(greenFlashTimeoutRef.current);
    };
  }, [isListening, i18n.language, processText, setTranscript]);

  return {
    isListening,
    transcript,
    lastCommand,
    startListening,
    stopListening
  };
}

import { getBrowserClient } from '@/lib/supabase/browser';
import mqtt from 'mqtt';

export interface SOSTelemetry {
  name: string;
  age: string;
  bloodGroup: string;
  conditions: string;
  allergies: string;
  emergencyContacts: { name: string; phone: string; relationship?: string }[];
  lat: number;
  lng: number;
  address: string;
  battery: number;
  network: string;
  speed: number;
  timestamp: number;
  deviceInfo: string;
}

export interface BroadcastChannelResult {
  channel: string;
  status: 'sent' | 'failed' | 'unavailable';
  detail: string;
}

function formatSOSMessage(data: SOSTelemetry): string {
  const mapLink = `https://www.google.com/maps?q=${data.lat},${data.lng}`;
  const speedKmh = Math.round((data.speed || 0) * 3.6);

  return `⚠️ EMERGENCY SOS ALERT! ⚠️
Name: ${data.name} (Age: ${data.age})
Blood Group: ${data.bloodGroup}
Conditions: ${data.conditions || 'None'}
Allergies: ${data.allergies || 'None'}
Location: ${data.address}
Maps Link: ${mapLink}
Battery: ${data.battery}% | Network: ${data.network}
Speed: ${speedKmh} km/h`;
}

export async function broadcastSOS(sosData: SOSTelemetry): Promise<BroadcastChannelResult[]> {
  const message = formatSOSMessage(sosData);
  const contacts = sosData.emergencyContacts || [];

  // Create all channel promises
  const channels: { name: string; promise: () => Promise<BroadcastChannelResult> }[] = [
    // 1. SMS via Twilio
    {
      name: 'sms',
      promise: async () => {
        if (contacts.length === 0) {
          return { channel: 'sms', status: 'unavailable', detail: 'No emergency contacts registered' };
        }

        try {
          const res = await fetch('/api/sos/sms', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              to: contacts.map((c) => c.phone),
              message
            })
          });

          if (!res.ok) {
            const errText = await res.text();
            throw new Error(errText || 'Failed to send SMS');
          }

          return { channel: 'sms', status: 'sent', detail: `SMS sent to ${contacts.length} contact(s)` };
        } catch (err: any) {
          return { channel: 'sms', status: 'failed', detail: err.message || 'SMS service error' };
        }
      }
    },

    // 2. WhatsApp Deep Link
    {
      name: 'whatsapp',
      promise: async () => {
        if (typeof window === 'undefined') {
          return { channel: 'whatsapp', status: 'unavailable', detail: 'Browser context needed' };
        }

        try {
          const waUrl = `https://wa.me/?text=${encodeURIComponent(message)}`;
          window.open(waUrl, '_blank');
          return { channel: 'whatsapp', status: 'sent', detail: 'WhatsApp share page opened' };
        } catch (err: any) {
          return { channel: 'whatsapp', status: 'failed', detail: err.message || 'WhatsApp launch failed' };
        }
      }
    },

    // 3. Email via API
    {
      name: 'email',
      promise: async () => {
        try {
          const res = await fetch('/api/sos/email', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(sosData)
          });

          if (!res.ok) {
            const errText = await res.text();
            throw new Error(errText || 'Failed to dispatch email');
          }

          return { channel: 'email', status: 'sent', detail: 'Emergency email alerts dispatched' };
        } catch (err: any) {
          return { channel: 'email', status: 'failed', detail: err.message || 'Email dispatch error' };
        }
      }
    },

    // 4. Push Notification via API
    {
      name: 'push',
      promise: async () => {
        try {
          const res = await fetch('/api/sos/push', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(sosData)
          });

          if (!res.ok) {
            const errText = await res.text();
            throw new Error(errText || 'Failed to send Push Notifications');
          }

          return { channel: 'push', status: 'sent', detail: 'Push notification sent to contact devices' };
        } catch (err: any) {
          return { channel: 'push', status: 'failed', detail: err.message || 'Push service error' };
        }
      }
    },

    // 5. Web Bluetooth Scan / Broadcast
    {
      name: 'bluetooth',
      promise: async () => {
        if (typeof navigator === 'undefined' || !(navigator as any).bluetooth) {
          return { channel: 'bluetooth', status: 'unavailable', detail: 'Web Bluetooth not supported by browser' };
        }

        try {
          // Attempting requestDevice to advertise/establish pairing as broadcast trigger
          await (navigator as any).bluetooth.requestDevice({ acceptAllDevices: true });
          return { channel: 'bluetooth', status: 'sent', detail: 'Bluetooth advertisement initiated' };
        } catch (err: any) {
          if (err.name === 'NotSupportedError') {
            return { channel: 'bluetooth', status: 'unavailable', detail: 'Bluetooth hardware not available' };
          }
          return { channel: 'bluetooth', status: 'failed', detail: err.message || 'Bluetooth connection rejected' };
        }
      }
    },

    // 6. Web Serial Link
    {
      name: 'serial',
      promise: async () => {
        if (typeof navigator === 'undefined' || !('serial' in navigator)) {
          return { channel: 'serial', status: 'unavailable', detail: 'Web Serial not supported by browser' };
        }

        try {
          await (navigator as any).serial.requestPort();
          return { channel: 'serial', status: 'sent', detail: 'Serial alert sent to port' };
        } catch (err: any) {
          return { channel: 'serial', status: 'unavailable', detail: err.message || 'No active serial device selected' };
        }
      }
    },

    // 7. Supabase Realtime Broadcast
    {
      name: 'websocket',
      promise: async () => {
        try {
          const supabase = getBrowserClient();
          if (!supabase) {
            return { channel: 'websocket', status: 'unavailable', detail: 'Supabase client not initialized' };
          }

          const channel = supabase.channel('sos_events');

          const response = await channel.send({
            type: 'broadcast',
            event: 'sos',
            payload: {
              ...sosData,
              timestamp: Date.now()
            }
          });

          if (response !== 'ok') {
            throw new Error(`Realtime channel returned status: ${response}`);
          }

          return { channel: 'websocket', status: 'sent', detail: 'Realtime map telemetry broadcasted' };
        } catch (err: any) {
          return { channel: 'websocket', status: 'failed', detail: err.message || 'Realtime broadcast error' };
        }
      }
    },

    // 8. MQTT over WebSocket via HiveMQ Public Broker
    {
      name: 'mqtt',
      promise: () => {
        return new Promise<BroadcastChannelResult>((resolve) => {
          try {
            const userNameSanitized = sosData.name.toLowerCase().replace(/[^a-z0-9]/g, '_') || 'anon';
            const topic = `emergency/sos/${userNameSanitized}`;

            // Connect to HiveMQ Public Broker via encrypted WebSocket
            const client = mqtt.connect('wss://broker.hivemq.com:8000/mqtt', {
              connectTimeout: 4000,
              reconnectPeriod: 0 // do not auto-reconnect on fail
            });

            let resolved = false;

            const cleanupAndResolve = (result: BroadcastChannelResult) => {
              if (resolved) return;
              resolved = true;
              try {
                client.end(true);
              } catch {}
              resolve(result);
            };

            client.on('connect', () => {
              client.publish(topic, JSON.stringify(sosData), { qos: 1 }, (publishErr) => {
                if (publishErr) {
                  cleanupAndResolve({ channel: 'mqtt', status: 'failed', detail: publishErr.message });
                } else {
                  cleanupAndResolve({ channel: 'mqtt', status: 'sent', detail: `Published to HiveMQ topic: ${topic}` });
                }
              });
            });

            client.on('error', (err) => {
              cleanupAndResolve({ channel: 'mqtt', status: 'failed', detail: err.message || 'MQTT error' });
            });

            // Fail if timeout exceeded
            setTimeout(() => {
              cleanupAndResolve({ channel: 'mqtt', status: 'failed', detail: 'Connection to HiveMQ timed out' });
            }, 5000);

          } catch (err: any) {
            resolve({ channel: 'mqtt', status: 'failed', detail: err.message || 'MQTT init failed' });
          }
        });
      }
    }
  ];

  // Execute all channels concurrently using settled promises
  const settles = await Promise.allSettled(channels.map((ch) => ch.promise()));

  return settles.map((settled, idx) => {
    const chName = channels[idx].name;
    if (settled.status === 'fulfilled') {
      return settled.value;
    } else {
      return {
        channel: chName,
        status: 'failed',
        detail: settled.reason?.message || 'Uncaught error in channel promise'
      };
    }
  });
}

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { nanoid } from 'nanoid';

export type SOSStatus = 'idle' | 'countdown' | 'active' | 'acknowledged' | 'resolved';
export type TriggerType = 'manual' | 'crash' | 'shake' | 'triple-press' | 'voice' | 'scheduled' | 'rollover';

export interface SOSLocation {
  lat: number;
  lng: number;
  address: string;
  accuracy?: number;
  speed?: number;
  timestamp: number;
}

export interface SOSTelemetry {
  name: string;
  age: string;
  bloodGroup: string;
  conditions: string;
  allergies: string;
  emergencyContacts: { name: string; phone: string; relationship?: string }[];
  lat: number;
  lng: number;
  address: string;
  battery: number;
  network: string;
  speed: number;
  timestamp: number;
  deviceInfo: string;
}

export interface BroadcastStatus {
  sms: 'pending' | 'sent' | 'failed' | 'unavailable';
  whatsapp: 'pending' | 'sent' | 'failed' | 'unavailable';
  push: 'pending' | 'sent' | 'failed' | 'unavailable';
  websocket: 'pending' | 'sent' | 'failed' | 'unavailable';
  bluetooth: 'pending' | 'sent' | 'failed' | 'unavailable';
  email: 'pending' | 'sent' | 'failed' | 'unavailable';
  mqtt: 'pending' | 'sent' | 'failed' | 'unavailable';
  serial: 'pending' | 'sent' | 'failed' | 'unavailable';
}

export interface Responder {
  name: string;
  lat: number;
  lng: number;
  etaMinutes: number;
  id?: string;
  assignedAt?: number;
}

interface SOSState {
  status: SOSStatus;
  countdownSeconds: number;
  incidentId: string | null;
  location: SOSLocation | null;
  trigger: TriggerType | null;
  broadcastStatus: BroadcastStatus | null;
  responder: Responder | null;
  autoDialed: boolean;
  telemetryData: SOSTelemetry | null;

  // Actions
  arm: (trigger?: TriggerType, customCountdown?: number) => void;
  cancel: () => void;
  broadcast: () => Promise<void>;
  resolve: () => void;
  allClear: () => Promise<void>;
  setLocation: (location: SOSLocation) => void;
  tickCountdown: () => void;
  setAutoDialed: (val: boolean) => void;
}

const DEFAULT_BROADCAST: BroadcastStatus = {
  sms: 'pending', whatsapp: 'pending', push: 'pending',
  websocket: 'pending', bluetooth: 'pending', email: 'pending',
  mqtt: 'pending', serial: 'pending'
};

export const useSOSStore = create<SOSState>()(
  persist(
    (set, get) => ({
      status: 'idle',
      countdownSeconds: 30,
      incidentId: null,
      location: null,
      trigger: null,
      broadcastStatus: null,
      responder: null,
      autoDialed: false,
      telemetryData: null,

      arm: (trigger = 'manual', customCountdown = 30) => {
        const incidentId = nanoid();
        const startStatus = trigger === 'crash' ? 'active' : 'countdown';

        set({
          status: startStatus,
          countdownSeconds: trigger === 'crash' ? 0 : customCountdown,
          trigger,
          incidentId,
          broadcastStatus: { ...DEFAULT_BROADCAST },
          autoDialed: false,
          telemetryData: null,
        });

        // Initialize telemetry synchronously with available data
        const telemetry: SOSTelemetry = {
          name: 'Unknown User',
          age: 'Unknown',
          bloodGroup: 'Unknown',
          conditions: '',
          allergies: '',
          emergencyContacts: [],
          lat: 0,
          lng: 0,
          address: 'Locating user...',
          battery: 100,
          network: 'unknown',
          speed: 0,
          timestamp: Date.now(),
          deviceInfo: `UA: ${navigator.userAgent} | Screen: ${window.screen.width}x${window.screen.height} @ DPR ${window.devicePixelRatio || 1}`,
        };

        // Try load profile from localStorage
        try {
          const profileStr = localStorage.getItem('roadsos-profile');
          if (profileStr) {
            const profile = JSON.parse(profileStr);
            telemetry.name = profile.name || telemetry.name;
            if (profile.dob) {
              const birthYear = new Date(profile.dob).getFullYear();
              if (!isNaN(birthYear)) {
                telemetry.age = String(new Date().getFullYear() - birthYear);
              }
            }
            telemetry.bloodGroup = profile.bloodGroup || telemetry.bloodGroup;
            telemetry.conditions = profile.conditions || telemetry.conditions;
            telemetry.allergies = profile.allergies || telemetry.allergies;
            telemetry.emergencyContacts = profile.emergencyContacts || [];
          }
        } catch (e) {
          console.warn('[SOS Store] Local profile read error:', e);
        }

        // Fetch network speed / type
        const conn = (navigator as any).connection || (navigator as any).mozConnection || (navigator as any).webkitConnection;
        if (conn) {
          telemetry.network = conn.effectiveType || conn.type || 'unknown';
        }

        const gatherAsyncTelemetry = async () => {
          // 1. Get Battery
          try {
            if ('getBattery' in navigator) {
              const b = await (navigator as any).getBattery();
              telemetry.battery = Math.round(b.level * 100);
            }
          } catch {}

          // 2. Get Geolocation
          const getGeo = () => new Promise<GeolocationPosition>((resolve, reject) => {
            navigator.geolocation?.getCurrentPosition(resolve, reject, {
              enableHighAccuracy: true,
              timeout: trigger === 'crash' ? 2000 : 8000,
              maximumAge: 0
            });
          });

          try {
            const pos = await getGeo();
            telemetry.lat = pos.coords.latitude;
            telemetry.lng = pos.coords.longitude;
            telemetry.speed = pos.coords.speed || 0;
            telemetry.address = `${pos.coords.latitude.toFixed(5)}, ${pos.coords.longitude.toFixed(5)}`;

            const loc: SOSLocation = {
              lat: pos.coords.latitude,
              lng: pos.coords.longitude,
              address: telemetry.address,
              accuracy: pos.coords.accuracy,
              timestamp: Date.now(),
            };
            set({ location: loc });

            // nominatim reverse geocode
            try {
              const r = await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${loc.lat}&lon=${loc.lng}&format=json`);
              const data = await r.json();
              if (data.display_name) {
                loc.address = data.display_name;
                telemetry.address = data.display_name;
                set({ location: loc });
              }
            } catch {}
          } catch (err) {
            console.warn('[SOS Store] Geolocation error:', err);
            const fallbackLoc = { lat: 0, lng: 0, address: 'Location unavailable', timestamp: Date.now() };
            set({ location: fallbackLoc });
            telemetry.lat = 0;
            telemetry.lng = 0;
            telemetry.address = 'Location unavailable';
          }

          // 3. Merge database profile if active session exists
          try {
            const res = await fetch('/api/profile');
            if (res.ok) {
              const data = await res.json();
              if (data.profile) {
                telemetry.name = data.profile.full_name || telemetry.name;
                telemetry.bloodGroup = data.profile.blood_group || telemetry.bloodGroup;
                telemetry.conditions = data.profile.medical_conditions?.join(', ') || telemetry.conditions;
                telemetry.allergies = data.profile.allergies?.join(', ') || telemetry.allergies;
                if (data.profile.date_of_birth) {
                  const birthYear = new Date(data.profile.date_of_birth).getFullYear();
                  if (!isNaN(birthYear)) {
                    telemetry.age = String(new Date().getFullYear() - birthYear);
                  }
                }
              }
              if (Array.isArray(data.contacts) && data.contacts.length > 0) {
                telemetry.emergencyContacts = data.contacts.map((c: any) => ({
                  name: c.name,
                  phone: c.phone,
                  relationship: c.relationship || c.relation || 'Emergency Contact'
                }));
              }
            }
          } catch {}

          // Finalize telemetry
          set({ telemetryData: telemetry });

          // If trigger is crash, we proceed to call broadcast() immediately
          if (trigger === 'crash') {
            void get().broadcast();
          }
        };

        void gatherAsyncTelemetry();
      },

      cancel: () => set({ status: 'idle', countdownSeconds: 30, incidentId: null, broadcastStatus: null, autoDialed: false, telemetryData: null }),

      broadcast: async () => {
        set({ status: 'active' });
        const { incidentId, telemetryData, location, trigger } = get();

        // Standard fallback payload if telemetry resolved late
        const sosPayload: SOSTelemetry = telemetryData || {
          name: 'Unknown User',
          age: 'Unknown',
          bloodGroup: 'Unknown',
          conditions: '',
          allergies: '',
          emergencyContacts: [],
          lat: location?.lat || 0,
          lng: location?.lng || 0,
          address: location?.address || 'Locating...',
          battery: 100,
          network: 'unknown',
          speed: 0,
          timestamp: Date.now(),
          deviceInfo: `UA: ${navigator.userAgent}`,
        };

        try {
          // Trigger server database logging (creates incident and sos_events record)
          const res = await fetch('/api/sos', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              incidentId,
              lat: sosPayload.lat,
              lng: sosPayload.lng,
              address: sosPayload.address,
              batteryLevel: sosPayload.battery,
              networkType: sosPayload.network,
              emergencyType: 'road_crash',
              triggerType: trigger || 'manual',
              telemetry: sosPayload,
            }),
          });

          if (res.ok) {
            const data = await res.json() as { responder?: Responder };
            if (data.responder) {
              set({ responder: data.responder });
            }
          }

          // Switch theme to high-contrast emergency mode
          document.documentElement.classList.add('emergency-high-contrast');

          // Trigger the local broadcast service (Phase 5)
          const { broadcastSOS } = await import('@/lib/sosbroadcast');
          const results = await broadcastSOS(sosPayload);

          // Update Zustand store's broadcastStatus with the outcomes of each channel
          const currentStatus = { ...DEFAULT_BROADCAST };
          results.forEach((r) => {
            const ch = r.channel as keyof BroadcastStatus;
            if (ch in currentStatus) {
              currentStatus[ch] = r.status as any;
            }
          });

          set({ broadcastStatus: currentStatus, status: 'acknowledged' });
        } catch (err) {
          console.error('[SOS Store] Broadcast error:', err);
          // Make sure we still stay in active emergency
          set({ status: 'active' });
        }
      },

      resolve: () => {
        document.documentElement.classList.remove('emergency-high-contrast');
        set({ status: 'resolved' });
      },

      allClear: async () => {
        const { incidentId, telemetryData } = get();
        document.documentElement.classList.remove('emergency-high-contrast');

        try {
          await fetch('/api/sos/all-clear', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              incidentId,
              contacts: telemetryData?.emergencyContacts || [],
              userName: telemetryData?.name || 'User',
            }),
          });
        } catch (err) {
          console.warn('[SOS Store] All-clear POST failed:', err);
        }

        set({ status: 'idle', countdownSeconds: 30, incidentId: null, broadcastStatus: null, autoDialed: false, telemetryData: null, responder: null });
      },

      setLocation: (location) => set({ location }),

      setAutoDialed: (val) => set({ autoDialed: val }),

      tickCountdown: () => {
        const { countdownSeconds, status, broadcast } = get();
        if (status !== 'countdown') return;
        if (countdownSeconds <= 1) {
          void broadcast();
        } else {
          set({ countdownSeconds: countdownSeconds - 1 });
        }
      },
    }),
    {
      name: 'roadsos-sos',
      partialize: (s) => ({
        location: s.location,
        status: s.status === 'active' || s.status === 'acknowledged' ? s.status : 'idle',
        telemetryData: s.telemetryData,
      }),
    }
  )
);

'use client';

import { useState, useEffect, useRef } from 'react';
import Peer from 'simple-peer';
import { io, Socket } from 'socket.io-client';
import { getBrowserClient } from './supabase/browser';

// Dynamic global variables to track active stream state for stop operations
let activeStream: MediaStream | null = null;
let activeSocket: Socket | null = null;
let activePeers: Record<string, Peer.Instance> = {};
let activeCanvasInterval: any = null;

export interface SOSEventPayload {
  userId: string;
  sosEventId: string;
  userInfo: {
    name: string;
    bloodGroup: string;
    conditions: string;
    allergies: string;
  };
  location: {
    lat: number;
    lng: number;
    address: string;
  };
}

/**
 * Requests browser media access. Falls back to audio-only, then to null.
 */
export async function initStream(): Promise<MediaStream | null> {
  if (typeof window === 'undefined' || !navigator.mediaDevices) return null;

  try {
    // 1. Attempt high-fidelity video & audio
    const stream = await navigator.mediaDevices.getUserMedia({
      video: {
        width: { ideal: 640 },
        height: { ideal: 480 },
        frameRate: { ideal: 15 }
      },
      audio: true
    });
    return stream;
  } catch (videoErr) {
    console.warn('[WebRTC] Video capture blocked/unavailable. Attempting audio fallback...', videoErr);
    try {
      // 2. Fallback to audio only
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      return stream;
    } catch (audioErr) {
      console.warn('[WebRTC] Both video and audio permissions blocked.', audioErr);
      return null;
    }
  }
}

/**
 * Creates standard simple-peer connection wrapped around RTCPeerConnection with Google STUN servers.
 */
export function createPeerConnection(
  stream: MediaStream | null,
  initiator: boolean = true
): Peer.Instance {
  return new Peer({
    initiator,
    trickle: true,
    stream: stream || undefined,
    config: {
      iceServers: [
        { urls: 'stun:stun.l.google.com:19302' },
        { urls: 'stun:stun1.l.google.com:19302' }
      ]
    }
  });
}

/**
 * Burns critical emergency metadata directly onto the video stream using canvas
 */
export function burnMetadataToStream(
  originalStream: MediaStream,
  metadata: { name: string; lat: number; lng: number; bloodGroup: string; sosId: string }
): MediaStream {
  if (typeof window === 'undefined' || originalStream.getVideoTracks().length === 0) {
    return originalStream;
  }

  try {
    const video = document.createElement('video');
    video.srcObject = originalStream;
    video.muted = true;
    video.playsInline = true;
    void video.play();

    const canvas = document.createElement('canvas');
    canvas.width = 640;
    canvas.height = 480;
    const ctx = canvas.getContext('2d');

    if (!ctx) return originalStream;

    const drawFrame = () => {
      if (video.paused || video.ended) return;

      // Draw original camera frame
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

      // Burn semi-transparent black strip at bottom for legibility
      ctx.fillStyle = 'rgba(0, 0, 0, 0.65)';
      ctx.fillRect(0, canvas.height - 70, canvas.width, 70);

      // Render Telemetry metadata
      ctx.font = 'bold 11px monospace';
      ctx.fillStyle = '#ef4444'; // Red accent
      ctx.fillText('🚨 ROADSoS EMERGENCY STREAM', 15, canvas.height - 50);

      ctx.fillStyle = '#ffffff';
      ctx.font = '10px monospace';
      ctx.fillText(`ID  : ${metadata.sosId.substring(0, 10).toUpperCase()}`, 15, canvas.height - 35);
      ctx.fillText(`NAME: ${metadata.name.toUpperCase()}`, 15, canvas.height - 20);

      const latStr = metadata.lat ? metadata.lat.toFixed(5) : '0.00000';
      const lngStr = metadata.lng ? metadata.lng.toFixed(5) : '0.00000';
      ctx.fillText(`GPS : ${latStr}, ${lngStr}`, 280, canvas.height - 35);
      ctx.fillText(`BLOOD GROUP: ${metadata.bloodGroup}`, 280, canvas.height - 20);
      ctx.fillText(`TIME: ${new Date().toLocaleTimeString()}`, 280, canvas.height - 50);
    };

    // 15 FPS Loop
    const interval = setInterval(drawFrame, 1000 / 15);
    activeCanvasInterval = interval;

    // Capture dynamic stream from canvas
    const canvasStream = canvas.captureStream(15);

    // Merge audio tracks back
    originalStream.getAudioTracks().forEach((track) => {
      canvasStream.addTrack(track);
    });

    return canvasStream;
  } catch (err) {
    console.error('[WebRTC] Metadata burning failed:', err);
    return originalStream;
  }
}

/**
 * Initializes and starts emergency broadcasting loops.
 */
export async function startEmergencyStream(
  userId: string,
  sosEventId: string
): Promise<{
  stream: MediaStream | null;
  peers: Record<string, Peer.Instance>;
  stop: () => void;
}> {
  console.log(`[WebRTC] Starting emergency stream for user ${userId}, Event ID: ${sosEventId}`);

  // 1. Fetch user media stream
  const rawStream = await initStream();
  let stream = rawStream;

  // 2. Fetch User profile coordinates and details
  let userName = 'Unknown User';
  let bloodGroup = 'Unknown';
  let conditions = '';
  let allergies = '';
  let contacts: { name: string; phone: string }[] = [];
  let lat = 0;
  let lng = 0;
  let address = 'Locating...';

  try {
    const saved = localStorage.getItem('roadsos-profile');
    if (saved) {
      const profile = JSON.parse(saved);
      userName = profile.name || userName;
      bloodGroup = profile.bloodGroup || bloodGroup;
      conditions = profile.conditions || conditions;
      allergies = profile.allergies || allergies;
      contacts = profile.contacts || [];
    }

    // Try loading lat/lng from active SOS coordinates in session storage or state
    const sosCache = localStorage.getItem('roadsos-sos');
    if (sosCache) {
      const cached = JSON.parse(sosCache);
      if (cached.location) {
        lat = cached.location.lat;
        lng = cached.location.lng;
        address = cached.location.address || address;
      }
    }
  } catch (e) {
    console.warn('[WebRTC] Profile reading error:', e);
  }

  // 3. Burn metadata overlay if video is running
  if (stream && stream.getVideoTracks().length > 0) {
    stream = burnMetadataToStream(stream, {
      name: userName,
      lat,
      lng,
      bloodGroup,
      sosId: sosEventId
    });
  }

  activeStream = stream;

  // 4. Connect to socket.io signaling server
  const signalingUrl = process.env.NEXT_PUBLIC_SIGNALING_URL || 'ws://localhost:3001';
  console.log(`[WebRTC] Connecting to signaling server at: ${signalingUrl}`);

  const socket = io(signalingUrl, {
    transports: ['websocket'],
    timeout: 5000,
    reconnection: true
  });
  activeSocket = socket;

  const peers: Record<string, Peer.Instance> = {};
  activePeers = peers;

  socket.on('connect', () => {
    console.log('[WebRTC] Connected to signaling channel successfully');

    // Register victim channel mapping
    socket.emit('register', { userId, role: 'victim', sosEventId });

    // Emit stream initialization event to signaling broker
    const eventPayload: SOSEventPayload = {
      userId,
      sosEventId,
      userInfo: { name: userName, bloodGroup, conditions, allergies },
      location: { lat, lng, address }
    };
    socket.emit('sos-stream-start', eventPayload);
  });

  // 5. Setup WebRTC Peer Connection per registered contact
  contacts.forEach((contact) => {
    const contactKey = contact.phone;
    console.log(`[WebRTC] Initializing connection for contact: ${contact.name} (${contactKey})`);

    const peer = new Peer({
      initiator: true,
      trickle: true,
      stream: stream || undefined,
      config: {
        iceServers: [
          { urls: 'stun:stun.l.google.com:19302' },
          { urls: 'stun:stun1.l.google.com:19302' }
        ]
      }
    });

    peer.on('signal', (signal) => {
      // Send signal via socket broker to specifically target this contact
      socket.emit('signal', {
        to: contactKey,
        from: userId,
        sosEventId,
        signal
      });
    });

    peer.on('connect', () => {
      console.log(`[WebRTC] Connected peer link to contact: ${contact.name}`);
    });

    peer.on('error', (err) => {
      console.warn(`[WebRTC] Peer error on contact: ${contact.name}`, err);
    });

    peers[contactKey] = peer;
  });

  // Listen for incoming signal callbacks from administration control rooms or contact receivers
  socket.on('signal', (data: { from: string; signal: any }) => {
    const peer = peers[data.from] || activePeers[data.from];
    if (peer) {
      peer.signal(data.signal);
    } else {
      // Admin control room signaling or new connection mapping
      console.log(`[WebRTC] Incoming signal from unmapped peer: ${data.from}. Mapping dynamically...`);
      const newPeer = new Peer({
        initiator: false,
        trickle: true,
        stream: stream || undefined,
        config: {
          iceServers: [
            { urls: 'stun:stun.l.google.com:19302' }
          ]
        }
      });

      newPeer.on('signal', (signal) => {
        socket.emit('signal', {
          to: data.from,
          from: userId,
          sosEventId,
          signal
        });
      });

      newPeer.on('connect', () => {
        console.log(`[WebRTC] Connected dynamic peer link to: ${data.from}`);
      });

      newPeer.signal(data.signal);
      peers[data.from] = newPeer;
    }
  });

  const stop = () => {
    stopEmergencyStream();
  };

  return { stream, peers, stop };
}

/**
 * Terminates all emergency streams, closes sockets, releases tracks, and saves final logs.
 */
export function stopEmergencyStream() {
  console.log('[WebRTC] Stopping emergency stream and cleanups');

  // 1. Stop canvas overlay loop
  if (activeCanvasInterval) {
    clearInterval(activeCanvasInterval);
    activeCanvasInterval = null;
  }

  // 2. Close simple-peer coordinates
  Object.keys(activePeers).forEach((key) => {
    try {
      activePeers[key].destroy();
    } catch {}
  });
  activePeers = {};

  // 3. Stop all media tracks
  if (activeStream) {
    activeStream.getTracks().forEach((track) => {
      try {
        track.stop();
      } catch {}
    });
    activeStream = null;
  }

  // 4. Notify signaling server and close socket link
  if (activeSocket) {
    try {
      activeSocket.emit('sos-stream-stop');
      activeSocket.disconnect();
    } catch {}
    activeSocket = null;
  }

  // 5. Trigger final DB saves (updates status inside Supabase incidents)
  try {
    const supabase = getBrowserClient();
    if (supabase) {
      const sosCache = localStorage.getItem('roadsos-sos');
      if (sosCache) {
        const cached = JSON.parse(sosCache);
        if (cached.incidentId) {
          void supabase
            .from('incidents')
            .update({
              status: 'resolved',
              resolved_at: new Date().toISOString()
            })
            .eq('id', cached.incidentId);
        }
      }
    }
  } catch (err) {
    console.warn('[WebRTC] Failed to save final incident resolution to DB:', err);
  }
}

/**
 * React hook wrapping simple-peer WebRTC connection using Supabase Broadcast for signaling.
 */
export function useWebRTC(
  incidentId: string | null,
  role: 'victim' | 'admin',
  localStream: MediaStream | null = null,
  onRemoteStream?: (stream: MediaStream) => void
): { connected: boolean } {
  const [connected, setConnected] = useState(false);
  const peerRef = useRef<Peer.Instance | null>(null);
  const channelRef = useRef<any>(null);

  useEffect(() => {
    if (!incidentId) return;

    const supabase = getBrowserClient();
    if (!supabase) return;

    const channelName = `webrtc-signaling-${incidentId}`;
    const channel = supabase.channel(channelName);
    channelRef.current = channel;

    const initPeer = (isInitiator: boolean) => {
      if (peerRef.current) {
        try {
          peerRef.current.destroy();
        } catch {}
      }

      console.log(`[useWebRTC] Initializing peer, role: ${role}, initiator: ${isInitiator}`);
      const peer = new Peer({
        initiator: isInitiator,
        trickle: true,
        stream: localStream || undefined,
        config: {
          iceServers: [
            { urls: 'stun:stun.l.google.com:19302' },
            { urls: 'stun:stun1.l.google.com:19302' }
          ]
        }
      });

      peer.on('signal', (signal) => {
        console.log(`[useWebRTC] Generated signal, broadcasting from ${role}`);
        void channel.send({
          type: 'broadcast',
          event: 'signal',
          payload: { role, signal }
        });
      });

      peer.on('connect', () => {
        console.log(`[useWebRTC] Peer connected successfully, role: ${role}`);
        setConnected(true);
      });

      peer.on('stream', (remoteStream) => {
        console.log(`[useWebRTC] Remote stream received in hook, role: ${role}`);
        if (onRemoteStream) {
          onRemoteStream(remoteStream);
        }
      });

      peer.on('error', (err) => {
        console.error('[useWebRTC] Peer error:', err);
      });

      peerRef.current = peer;
      return peer;
    };

    // If we are the victim, we can initiate the peer connection immediately if localStream is available
    if (role === 'victim' && localStream) {
      initPeer(true);
    }

    channel
      .on('broadcast', { event: 'signal' }, ({ payload }) => {
        const { role: senderRole, signal } = payload;
        if (senderRole === role) return; // Ignore our own signals

        console.log(`[useWebRTC] Received signal from ${senderRole}`);
        let peer = peerRef.current;
        if (!peer) {
          // If we are admin and victim sends signal, we initialize as non-initiator
          if (role === 'admin' && senderRole === 'victim') {
            peer = initPeer(false);
          }
        }

        if (peer) {
          try {
            peer.signal(signal);
          } catch (e) {
            console.error('[useWebRTC] Error signaling peer:', e);
          }
        }
      })
      .subscribe((status) => {
        console.log(`[useWebRTC] Supabase realtime signaling channel status: ${status}`);
      });

    return () => {
      console.log(`[useWebRTC] Cleaning up peer hook for incident: ${incidentId}`);
      if (peerRef.current) {
        try {
          peerRef.current.destroy();
        } catch {}
        peerRef.current = null;
      }
      if (channel) {
        void supabase.removeChannel(channel);
      }
      setConnected(false);
    };
  }, [incidentId, role, localStream, onRemoteStream]);

  return { connected };
}

